// 🔑 슈퍼어드민 — 사업장 관리자 목록 조회 (TO 한도 설정용)
// ═══════════════════════════════════════════════════════════
// 이전: to_limit_settings_screen users 직접 list 쿼리 (USER list CF 정책 위반)
// 현재: Admin SDK 경유 — SUPER_ADMIN 검증 후 BUSINESS_ADMIN 목록 반환
export const callableGetBusinessAdmins = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    if (!request.auth) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");
    const callerSnap = await db.collection("users").doc(request.auth.uid).get();
    if (callerSnap.data()?.["role"] !== "SUPER_ADMIN") {
      throw new HttpsError("permission-denied", "슈퍼관리자 권한이 필요합니다.");
    }
    const snap = await db.collection("users")
      .where("role", "==", "BUSINESS_ADMIN")
      .orderBy("name")
      .limit(500)
      .get();
    const admins = snap.docs.map(d => {
      const data = d.data();
      return {
        uid: d.id,
        name: (data["name"] as string | undefined) ?? "이름 없음",
        businessName: (data["businessName"] as string | undefined) ?? null,
        managedBizCount: ((data["managedBusinessIds"] as unknown[] | undefined) ?? []).length,
        maxActiveTOs: (data["maxActiveTOs"] as number | undefined) ?? null,
      };
    });
    return {admins};
  }
);

// ═══════════════════════════════════════════════════════════
// 🔑 슈퍼어드민 — 관리자별 TO 한도 설정/초기화
// ═══════════════════════════════════════════════════════════
// 이전: to_limit_settings_screen users/{uid}.maxActiveTOs 직접 write (타인 데이터 CF 필수)
// 현재: Admin SDK 경유 — SUPER_ADMIN 검증 후 maxActiveTOs 갱신
export const callableSetAdminTOLimit = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    if (!request.auth) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");
    const callerSnap = await db.collection("users").doc(request.auth.uid).get();
    if (callerSnap.data()?.["role"] !== "SUPER_ADMIN") {
      throw new HttpsError("permission-denied", "슈퍼관리자 권한이 필요합니다.");
    }
    const {targetUid, value} = request.data as {targetUid?: string; value?: number | null};
    if (!targetUid) throw new HttpsError("invalid-argument", "targetUid가 필요합니다.");
    if (value === null || value === undefined) {
      await db.collection("users").doc(targetUid).update({
        maxActiveTOs: admin.firestore.FieldValue.delete(),
      });
    } else {
      if (typeof value !== "number" || !Number.isInteger(value) || value < 1 || value > 50) {
        throw new HttpsError("invalid-argument", "value는 1~50 사이의 정수여야 합니다.");
      }
      await db.collection("users").doc(targetUid).update({maxActiveTOs: value});
    }
    return {success: true};
  }
);

// ═══════════════════════════════════════════════════════════
// 🔑 슈퍼어드민 — 사업장 소유자 정보 일괄 조회
// ═══════════════════════════════════════════════════════════
// 이전: all_businesses_screen users whereIn 직접 쿼리 (USER list CF 정책 위반)
// 현재: Admin SDK 경유 — SUPER_ADMIN 검증 후 name/email만 반환
export const callableGetOwnerInfosByIds = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    if (!request.auth) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");
    const callerSnap = await db.collection("users").doc(request.auth.uid).get();
    if (callerSnap.data()?.["role"] !== "SUPER_ADMIN") {
      throw new HttpsError("permission-denied", "슈퍼관리자 권한이 필요합니다.");
    }
    const {ownerIds} = request.data as {ownerIds?: string[]};
    if (!ownerIds || !Array.isArray(ownerIds) || ownerIds.length === 0) return {owners: {}};
    if (ownerIds.length > 300) throw new HttpsError("invalid-argument", "ownerIds는 300개 이하여야 합니다.");
    const result: Record<string, {name: string; email: string; businessLicenseImageUrl: string | null}> = {};
    for (let i = 0; i < ownerIds.length; i += 30) {
      const chunk = ownerIds.slice(i, i + 30);
      const snap = await db.collection("users")
        .where(admin.firestore.FieldPath.documentId(), "in", chunk)
        .get();
      for (const doc of snap.docs) {
        const data = doc.data();
        result[doc.id] = {
          name: (data["name"] as string | undefined) ?? "알 수 없음",
          email: (data["email"] as string | undefined) ?? "",
          // [REG-2] legacy 사업자등록증 URL — users/{uid}.businessLicenseImageUrl
          // business.businessLicenseImageUrl이 없는 레거시 사업장의 SUPER_ADMIN 폴백 표시용
          businessLicenseImageUrl: (data["businessLicenseImageUrl"] as string | undefined) ?? null,
        };
      }
    }
    return {owners: result};
  }
);

// ═══════════════════════════════════════════════════════════
// 🔑 슈퍼어드민 — 사업자등록증 Signed URL 생성
// ═══════════════════════════════════════════════════════════
// [REG-2 SEC] businesses/{bizId}/license/ 경로: Storage rules allow get: if false
//   + 다운로드 토큰 없이 저장 → 클라이언트 직접 URL 접근 불가 (403)
//   SUPER_ADMIN이 검토 시 이 CF가 1시간 만료 Signed URL 발급
// Input:  { businessId: string }
// Output: { signedUrl: string }
export const callableGetBusinessLicenseSignedUrl = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    if (!request.auth) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");
    const callerSnap = await db.collection("users").doc(request.auth.uid).get();
    if (callerSnap.data()?.["role"] !== "SUPER_ADMIN") {
      throw new HttpsError("permission-denied", "슈퍼관리자 권한이 필요합니다.");
    }
    const {businessId} = request.data as {businessId?: string};
    if (!businessId || typeof businessId !== "string" || businessId.length > 100) {
      throw new HttpsError("invalid-argument", "businessId가 필요합니다.");
    }
    // 사업장 문서에서 businessLicenseImageUrl 조회
    const bizSnap = await db.collection("businesses").doc(businessId).get();
    const licenseUrl = bizSnap.data()?.["businessLicenseImageUrl"] as string | undefined;
    if (!licenseUrl) {
      throw new HttpsError("not-found", "사업자등록증이 등록되지 않은 사업장입니다.");
    }
    // URL에서 Storage 경로 추출: .../o/{encodedPath}?...
    const match = licenseUrl.match(/\/o\/([^?]+)/);
    if (!match) throw new HttpsError("internal", "사업자등록증 경로를 파싱할 수 없습니다.");
    const filePath = decodeURIComponent(match[1]);
    // 경로 검증: businesses/{bizId}/license/ 하위여야만 Signed URL 발급
    if (!filePath.startsWith(`businesses/${businessId}/license/`)) {
      throw new HttpsError("invalid-argument", "유효하지 않은 사업자등록증 경로입니다.");
    }
    const bucket = admin.storage().bucket();
    const [signedUrl] = await bucket.file(filePath).getSignedUrl({
      action: "read",
      expires: Date.now() + 60 * 60 * 1000, // 1시간 만료
      version: "v4",
    });
    return {signedUrl};
  }
);

// ═══════════════════════════════════════════════════════════
// 🏅 배지 평가 및 업데이트 (badge_service CF 이전)
// ═══════════════════════════════════════════════════════════
// 이전: badge_service.dart — attendance 직접 list 쿼리 (allow list: if false → PERMISSION_DENIED)
//       users/{uid}.badges 직접 write (슈퍼어드민 blocked 필드 목록에 badges 포함 → PERMISSION_DENIED)
// 현재: Admin SDK 경유 — 모든 attendance 쿼리 + badges write 서버에서 처리

// 배지 정의 (Dart BadgeModel.defaultBadges()와 동기화 필수)
type BadgeDef = {
  id: string;
  conditionType:
    | "minScore"
    | "workDays"
    | "consecutive"
    | "monthlyPerfect"
    | "nightShiftCount"
    | "earlyBirdCount"
    | "weekendCount"
    | "sameBusinessRehire"
    | "uniqueBusinesses";
  conditionValue: number;
  minWorkDays?: number;
  maxNoShow?: number;
  minRating?: number;
};

// attendance 전체 조회가 필요한 conditionType 집합
const ATTENDANCE_FETCH_TYPES = new Set<BadgeDef["conditionType"]>([
  "nightShiftCount",
  "earlyBirdCount",
  "weekendCount",
  "sameBusinessRehire",
  "uniqueBusinesses",
]);

const BADGE_DEFINITIONS: BadgeDef[] = [
  // 레벨 배지 (신뢰도 + 복합 조건)
  {id: "badge_bronze", conditionType: "minScore", conditionValue: 60, minWorkDays: 5},
  {id: "badge_silver", conditionType: "minScore", conditionValue: 70, minWorkDays: 20, maxNoShow: 1},
  {id: "badge_gold", conditionType: "minScore", conditionValue: 85, minWorkDays: 50, maxNoShow: 0},
  {id: "badge_diamond", conditionType: "minScore", conditionValue: 95, minWorkDays: 100, maxNoShow: 0, minRating: 4.5},
  // 경험 배지 (총 근무일수)
  {id: "badge_first_step", conditionType: "workDays", conditionValue: 10},
  {id: "badge_growing", conditionType: "workDays", conditionValue: 30},
  {id: "badge_experienced", conditionType: "workDays", conditionValue: 50},
  {id: "badge_veteran", conditionType: "workDays", conditionValue: 100},
  {id: "badge_master", conditionType: "workDays", conditionValue: 200},
  // 근태 배지
  {id: "badge_streak", conditionType: "consecutive", conditionValue: 15},
  {id: "badge_time_master", conditionType: "consecutive", conditionValue: 30},
  {id: "badge_perfect_attendance", conditionType: "monthlyPerfect", conditionValue: 1},
  // 도전 배지 (Steam 업적 스타일)
  {id: "badge_night_warrior", conditionType: "nightShiftCount", conditionValue: 15},
  {id: "badge_early_bird", conditionType: "earlyBirdCount", conditionValue: 20},
  {id: "badge_regular", conditionType: "sameBusinessRehire", conditionValue: 5},
  {id: "badge_traveler", conditionType: "uniqueBusinesses", conditionValue: 3},
  {id: "badge_weekend_warrior", conditionType: "weekendCount", conditionValue: 20},
  {id: "badge_explorer", conditionType: "uniqueBusinesses", conditionValue: 7},
  {id: "badge_vip_partner", conditionType: "sameBusinessRehire", conditionValue: 15},
];

// 도전 배지용 attendance 캐시 — 동일 평가 호출 내에서 여러 배지가 같은 쿼리를 중복 실행하지 않도록
type AttendanceCache = {
  docs: FirebaseFirestore.QueryDocumentSnapshot<FirebaseFirestore.DocumentData>[];
};

async function fetchAttendanceCache(uid: string): Promise<AttendanceCache> {
  const snap = await db.collection("attendance")
    .where("userId", "==", uid)
    .where("status", "in", ["present", "late", "early_leave"])
    .get();
  return {docs: snap.docs};
}

async function evaluateBadge(
  uid: string,
  userData: FirebaseFirestore.DocumentData,
  badge: BadgeDef,
  attendanceCache: AttendanceCache | null
): Promise<boolean> {
  const KST_OFFSET_MS = 9 * 60 * 60 * 1000;
  const totalWorkDays = (userData.totalWorkDays as number | undefined) ?? 0;

  if (badge.conditionType === "minScore") {
    // [5A.2B] trustScore 시스템 제거 — minScore 배지 비활성화 (항상 false 반환)
    return false;
  }

  if (badge.conditionType === "workDays") {
    return totalWorkDays >= badge.conditionValue;
  }

  if (badge.conditionType === "consecutive") {
    const snap = await db.collection("attendance")
      .where("userId", "==", uid)
      .orderBy("workDate", "desc")
      .limit(badge.conditionValue + 5)
      .get();
    let streak = 0;
    for (const doc of snap.docs) {
      const status = doc.data().status as string | undefined;
      // [DESIGN] late(지각)는 연속 출근 스트릭을 끊는 의도적 설계 — workDays 배지(late 허용)와 구분
      if (status === "present" || status === "early_leave") {
        streak++;
        if (streak >= badge.conditionValue) return true;
      } else {
        break;
      }
    }
    return false;
  }

  if (badge.conditionType === "monthlyPerfect") {
    const nowKST = new Date(new Date().getTime() + KST_OFFSET_MS);
    const kstYear = nowKST.getUTCFullYear();
    const kstMonth = nowKST.getUTCMonth();
    // KST 자정 기준 쿼리 범위 — Firestore workDate는 KST midnight = UTC - 9h로 저장
    const firstOfLastMonth = new Date(Date.UTC(kstYear, kstMonth - 1, 1) - KST_OFFSET_MS);
    const firstOfThisMonth = new Date(Date.UTC(kstYear, kstMonth, 1) - KST_OFFSET_MS);
    const snap = await db.collection("attendance")
      .where("userId", "==", uid)
      .where("workDate", ">=", Timestamp.fromDate(firstOfLastMonth))
      .where("workDate", "<", Timestamp.fromDate(firstOfThisMonth))
      .get();
    if (snap.empty) return false;
    // [DESIGN] late(지각)는 출근 인정 — 미출근(absent/NO_SHOW)만 제외
    // consecutive 배지와 달리 monthlyPerfect는 지각도 "출근함"으로 허용
    return snap.docs.every((doc) => {
      const s = doc.data().status as string | undefined;
      return s !== "absent" && s !== "NO_SHOW";
    });
  }

  // ── 도전 배지 — attendanceCache 사용 (사전 패치, null이면 skip) ──────
  if (!attendanceCache) return false;
  const {docs} = attendanceCache;

  if (badge.conditionType === "nightShiftCount") {
    // 야간: 체크인 KST 시각 22:00 이상
    let count = 0;
    for (const doc of docs) {
      const checkIn = doc.data().checkIn as {toDate: () => Date} | undefined;
      if (!checkIn) continue;
      const kstHour = (checkIn.toDate().getUTCHours() + 9) % 24;
      if (kstHour >= 22) count++;
    }
    return count >= badge.conditionValue;
  }

  if (badge.conditionType === "earlyBirdCount") {
    // 새벽: 체크인 KST 시각 06:00 미만
    let count = 0;
    for (const doc of docs) {
      const checkIn = doc.data().checkIn as {toDate: () => Date} | undefined;
      if (!checkIn) continue;
      const kstHour = (checkIn.toDate().getUTCHours() + 9) % 24;
      if (kstHour < 6) count++;
    }
    return count >= badge.conditionValue;
  }

  if (badge.conditionType === "weekendCount") {
    // 주말: workDate KST 요일 0(일)·6(토)
    // workDate는 KST midnight UTC 저장 → +9h 하면 KST midnight → UTC day = KST day
    let count = 0;
    for (const doc of docs) {
      const workDate = doc.data().workDate as {toDate: () => Date} | undefined;
      if (!workDate) continue;
      const kstDate = new Date(workDate.toDate().getTime() + KST_OFFSET_MS);
      const day = kstDate.getUTCDay();
      if (day === 0 || day === 6) count++;
    }
    return count >= badge.conditionValue;
  }

  if (badge.conditionType === "sameBusinessRehire") {
    // 같은 사업장 최다 출근일 ≥ conditionValue
    const bizCounts = new Map<string, number>();
    for (const doc of docs) {
      const bizId = doc.data().businessId as string | undefined;
      if (!bizId) continue;
      bizCounts.set(bizId, (bizCounts.get(bizId) ?? 0) + 1);
    }
    const maxCount = bizCounts.size === 0 ? 0 : Math.max(...Array.from(bizCounts.values()));
    return maxCount >= badge.conditionValue;
  }

  if (badge.conditionType === "uniqueBusinesses") {
    // 서로 다른 사업장 수 ≥ conditionValue
    const uniqueBizIds = new Set<string>();
    for (const doc of docs) {
      const bizId = doc.data().businessId as string | undefined;
      if (bizId) uniqueBizIds.add(bizId);
    }
    return uniqueBizIds.size >= badge.conditionValue;
  }

  return false;
}

export const callableEvaluateAndUpdateBadges = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    if (!request.auth) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");
    const callerUid = request.auth.uid;

    const targetUid = request.data.uid as string | undefined;
    if (!targetUid || typeof targetUid !== "string" || targetUid.length === 0) {
      throw new HttpsError("invalid-argument", "uid가 필요합니다.");
    }

    // 권한: 슈퍼어드민 또는 자신에 대한 배지 평가만 허용
    if (callerUid !== targetUid) {
      const callerSnap = await db.collection("users").doc(callerUid).get();
      if ((callerSnap.data()?.role as string | undefined) !== "SUPER_ADMIN") {
        throw new HttpsError("permission-denied", "본인 계정에 대한 배지 평가만 가능합니다.");
      }
    }

    // Firestore badges 컬렉션에서 활성 배지 정의 로드 (슈퍼어드민 수정사항 반영)
    // 컬렉션이 비어 있으면 하드코딩된 BADGE_DEFINITIONS로 폴백
    const VALID_CONDITION_TYPES = new Set<BadgeDef["conditionType"]>([
      "minScore", "workDays", "consecutive", "monthlyPerfect",
      "nightShiftCount", "earlyBirdCount", "weekendCount",
      "sameBusinessRehire", "uniqueBusinesses",
    ]);
    const badgeDefsSnap = await db.collection("badges").where("isActive", "==", true).get();
    const badgeDefs: BadgeDef[] = badgeDefsSnap.empty
      ? BADGE_DEFINITIONS
      : badgeDefsSnap.docs
          .map((doc) => {
            const d = doc.data();
            const ct = d.conditionType as string;
            if (!VALID_CONDITION_TYPES.has(ct as BadgeDef["conditionType"])) {
              console.warn(`[badges] 알 수 없는 conditionType "${ct}" (doc: ${doc.id}), 건너뜀`);
              return null;
            }
            const cv = d.conditionValue as number | undefined;
            if (typeof cv !== "number") {
              console.warn(`[badges] conditionValue 누락 또는 비숫자 (doc: ${doc.id}), 건너뜀`);
              return null;
            }
            return {
              id: doc.id,
              conditionType: ct as BadgeDef["conditionType"],
              conditionValue: cv,
              minWorkDays: d.minWorkDaysRequired as number | undefined,
              maxNoShow: d.maxNoShowAllowed as number | undefined,
              minRating: d.minRatingRequired as number | undefined,
            } as BadgeDef;
          })
          .filter((b): b is BadgeDef => b !== null);

    const userSnap = await db.collection("users").doc(targetUid).get();
    if (!userSnap.exists) throw new HttpsError("not-found", "사용자를 찾을 수 없습니다.");
    const userData = userSnap.data()!;

    const currentBadges = new Set<string>(
      Array.isArray(userData.badges) ? (userData.badges as string[]) : []
    );

    const pendingBadges = badgeDefs.filter((b) => !currentBadges.has(b.id));

    // 도전 배지 중 미획득 항목이 있으면 attendance를 한 번만 조회 (중복 쿼리 방지)
    const needsAttendanceCache = pendingBadges.some((b) => ATTENDANCE_FETCH_TYPES.has(b.conditionType));
    const attendanceCache = needsAttendanceCache ? await fetchAttendanceCache(targetUid) : null;

    // [PERF-M11] 배지 평가 순차 루프 → Promise.allSettled 병렬화
    const evalResults = await Promise.allSettled(
      pendingBadges.map(async (badge) => {
        const earned = await evaluateBadge(targetUid, userData, badge, attendanceCache);
        return earned ? badge.id : null;
      })
    );
    const newlyEarned: string[] = evalResults
      .flatMap((r, i) => {
        if (r.status === "rejected") {
          const badgeId = pendingBadges[i]?.id ?? "?";
          console.warn(`[callableEvaluateAndUpdateBadges] 배지 ${badgeId} 평가 실패 (건너뜀):`, r.reason);
          return [];
        }
        return r.value ? [r.value] : [];
      });

    if (newlyEarned.length > 0) {
      await db.collection("users").doc(targetUid).update({
        badges: admin.firestore.FieldValue.arrayUnion(...newlyEarned),
      });
    }

    return {newBadges: newlyEarned};
  }
);

// ══════════════════════════════════════════════════════════════════════════════
// callableRequestInterimSettlement
// 근로자가 중간정산을 요청한다.
// 서버 검증: 고용 관계 확인 + attendanceIds 소유권·wageStatus + 중복 PENDING 방지
// 성공 시: interim_settlement_requests 문서 생성 + 관리자(들)에게 FCM
// ══════════════════════════════════════════════════════════════════════════════
export const callableRequestInterimSettlement = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    const callerUid = request.auth?.uid;
    if (!callerUid) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");

    const d = request.data as {
      businessId: string;
      applicationId: string;
      businessName: string;
      workerName: string;
      periodStart: string;
      periodEnd: string;
      attendanceIds: string[];
      requestedAmount: number;
      netAmount: number;
      requestReason?: string;
    };

    if (!d.businessId || !d.applicationId)
      throw new HttpsError("invalid-argument", "businessId, applicationId 필수");
    if (!Array.isArray(d.attendanceIds) || d.attendanceIds.length === 0)
      throw new HttpsError("invalid-argument", "attendanceIds 1건 이상 필수");
    if (d.attendanceIds.length > 100)
      throw new HttpsError("invalid-argument", "attendanceIds 최대 100건");
    // [PAY-CF01] 0원 요청 허용 시 중복 PENDING으로 정상 요청이 차단되는 버그 방지
    if ((d.requestedAmount ?? 0) <= 0 || (d.netAmount ?? 0) <= 0)
      throw new HttpsError("invalid-argument", "금액은 1 이상이어야 합니다.");

    // 1. 고용 관계 검증 (applications 컬렉션)
    const appSnap = await db.collection("applications").doc(d.applicationId).get();
    if (!appSnap.exists)
      throw new HttpsError("not-found", "지원 정보를 찾을 수 없습니다.");
    const appData = appSnap.data()!;
    if (appData.uid !== callerUid)
      throw new HttpsError("permission-denied", "본인의 지원 정보만 요청 가능합니다.");
    if (appData.businessId !== d.businessId)
      throw new HttpsError("permission-denied", "지원과 사업장이 일치하지 않습니다.");

    // 2. attendanceIds 소유권 + wageStatus 검증
    const attSnaps = await Promise.all(
      d.attendanceIds.map((id) => db.collection("attendance").doc(id).get())
    );
    // [BUG-01] 클라이언트 제공 requestedAmount/netAmount 무시 — 서버 측에서 finalWage/netWage 합산
    const invalidIds: string[] = [];
    let serverRequestedAmount = 0;
    let serverNetAmount = 0;
    for (const snap of attSnaps) {
      if (!snap.exists) { invalidIds.push(snap.id); continue; }
      const ad = snap.data()!;
      if (ad.userId !== callerUid || ad.businessId !== d.businessId || ad.wageStatus !== "confirmed") {
        invalidIds.push(snap.id);
      } else {
        const wage = (ad.finalWage as number | undefined) ?? 0;
        serverRequestedAmount += wage;
        // netWage는 wageDetail 하위 필드 — 최상위 ad.netWage는 항상 undefined이므로
        // wageDetail.netWage를 참조해야 실수령액(세후)이 정확히 집계된다.
        const wageDetail = ad.wageDetail as Record<string, number> | undefined;
        serverNetAmount += wageDetail?.netWage ?? wage;
      }
    }
    if (invalidIds.length > 0)
      throw new HttpsError("invalid-argument", `유효하지 않은 출근기록: ${invalidIds.join(", ")}`);
    if (serverRequestedAmount <= 0)
      throw new HttpsError("failed-precondition", "확정된 임금이 없어 중간정산 요청이 불가합니다.");

    // 3+4. [PAY-DUP01] TOCTOU 방지 — 중복 체크와 문서 생성을 트랜잭션으로 원자화
    const now = admin.firestore.Timestamp.now();
    const docRef = db.collection("interim_settlement_requests").doc();
    await db.runTransaction(async (tx) => {
      const dupQuery = db.collection("interim_settlement_requests")
        .where("workerId", "==", callerUid)
        .where("businessId", "==", d.businessId)
        .where("status", "==", "PENDING")
        .limit(1);
      const dupSnap = await tx.get(dupQuery);
      if (!dupSnap.empty)
        throw new HttpsError("already-exists", "이미 처리 대기 중인 중간정산 요청이 있습니다.");
      tx.set(docRef, {
        applicationId: d.applicationId,
        businessId: d.businessId,
        businessName: d.businessName ?? "",
        workerId: callerUid,
        workerName: d.workerName ?? "",
        periodStart: admin.firestore.Timestamp.fromDate(new Date(d.periodStart)),
        periodEnd: admin.firestore.Timestamp.fromDate(new Date(d.periodEnd)),
        attendanceIds: d.attendanceIds,
        requestedAmount: Math.round(serverRequestedAmount),
        netAmount: Math.round(serverNetAmount),
        ...(d.requestReason ? {requestReason: d.requestReason} : {}),
        status: "PENDING",
        createdAt: now,
        updatedAt: now,
      });
    });

    // 5. 관리자(들)에게 FCM (onNotificationCreated 트리거가 푸시 발송)
    const bizSnap = await db.collection("businesses").doc(d.businessId).get();
    const bizData = bizSnap.data();
    const adminIdSet = new Set<string>([
      ...(Array.isArray(bizData?.adminIds) ? (bizData!.adminIds as string[]) : []),
      ...(bizData?.ownerId ? [bizData!.ownerId as string] : []),
    ]);
    // [ISR-SELF-NOTIFY] 요청자(근로자)가 adminIdSet에 포함된 경우 자기발송 방지
    adminIdSet.delete(callerUid);
    // [FCM-BUG-E] canManageWage 서브어드민에게도 팬아웃 (callableApplyToTO 패턴 참조)
    try {
      const subAdmins = await getSubAdminsWithPermission(d.businessId, "canManageWage");
      subAdmins.forEach((id) => { if (!adminIdSet.has(id)) adminIdSet.add(id); });
    } catch (e) {
      console.warn("[callableRequestInterimSettlement] 서브어드민 조회 실패 (무시):", e);
    }
    const pStart = new Date(d.periodStart);
    const pEnd   = new Date(d.periodEnd);
    const periodText =
      `${pStart.getMonth() + 1}/${pStart.getDate()}~${pEnd.getMonth() + 1}/${pEnd.getDate()}`;

    await Promise.allSettled(
      [...adminIdSet].map((adminUid) =>
        db.collection("users").doc(adminUid).collection("notifications").add({
          userId: adminUid,
          type: "interimSettlementRequested",
          title: "중간정산 요청",
          body: `[${d.businessName}] ${d.workerName} 님이 ${periodText} ${d.attendanceIds.length}건 중간정산을 요청했습니다.`,
          data: {
            businessId: d.businessId,
            settlementRequestId: docRef.id,
            screen: "interimSettlementAdmin",
          },
          isRead: false,
          createdAt: now,
        })
      )
    );

    return {success: true, settlementRequestId: docRef.id};
  }
);

// ══════════════════════════════════════════════════════════════════════════════
// callableApproveInterimSettlement
// 관리자가 중간정산을 승인하고 이체예정일을 지정한다.
// PENDING → APPROVED + 금액 재계산 + attendance 개별 lock (activeInterimSettlementId)
// [PAY-08] attendance fresh read + 금액 서버 재고정 + lock atomic set
// ══════════════════════════════════════════════════════════════════════════════
export const callableApproveInterimSettlement = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    const callerUid = request.auth?.uid;
    if (!callerUid) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");

    const d = request.data as {
      settlementRequestId: string;
      businessId: string;
      scheduledTransferDate: string; // ISO 8601 (YYYY-MM-DD)
      transferNote?: string;
    };

    if (!d.settlementRequestId) throw new HttpsError("invalid-argument", "settlementRequestId 필수");
    if (!d.businessId) throw new HttpsError("invalid-argument", "businessId 필수");
    if (!d.scheduledTransferDate) throw new HttpsError("invalid-argument", "scheduledTransferDate 필수");

    // [BUG-02] "YYYY-MM-DD" → new Date() 파싱이 환경에 따라 로컬/UTC가 달라질 수 있음
    // → T00:00:00Z 명시로 항상 UTC 자정 파싱 보장 (FCM 날짜 표시 일치)
    const transferDate = new Date(d.scheduledTransferDate + "T00:00:00Z");
    if (isNaN(transferDate.getTime()))
      throw new HttpsError("invalid-argument", "scheduledTransferDate 형식 오류 (YYYY-MM-DD)");

    const {callerData: approveCallerData, bizData: approveBizData} = await assertBizAdmin(callerUid, d.businessId);
    // [ISR-APPROVE-PERM] 서브어드민 canManageWage 세부 권한 검증
    const approveAdminIds = (approveBizData?.adminIds as string[] | undefined) ?? [];
    if (
      (approveCallerData?.role as string | undefined) !== "SUPER_ADMIN" &&
      !approveAdminIds.includes(callerUid) &&
      (approveBizData?.ownerId as string | undefined) !== callerUid
    ) {
      const approveMemberSnap = await db.collection("businesses").doc(d.businessId).collection("members").doc(callerUid).get();
      const approvePerms = (approveMemberSnap.data()?.permissions as Record<string, boolean>) ?? {};
      if (approvePerms.canManageWage !== true) throw new HttpsError("permission-denied", "임금 관리 권한이 없습니다.");
    }

    const reqRef = db.collection("interim_settlement_requests").doc(d.settlementRequestId);
    let workerId = "";
    let savedReqData: FirebaseFirestore.DocumentData | null = null;

    await db.runTransaction(async (tx) => {
      // [PAY-08] TX 내 fresh read: request + 모든 attendance
      const reqSnap = await tx.get(reqRef);
      if (!reqSnap.exists) throw new HttpsError("not-found", "중간정산 요청을 찾을 수 없습니다.");

      const rd = reqSnap.data()!;
      if (rd.businessId !== d.businessId)
        throw new HttpsError("permission-denied", "사업장 불일치");
      if (rd.status !== "PENDING")
        throw new HttpsError("failed-precondition", "PENDING 상태인 요청만 승인 가능합니다.");

      workerId = rd.workerId as string;
      savedReqData = rd;

      const attendanceIds = Array.isArray(rd.attendanceIds) ? (rd.attendanceIds as string[]) : [];
      if (attendanceIds.length === 0) throw new HttpsError("failed-precondition", "정산 대상 출근기록이 없습니다.");

      // [PAY-08] TX 내 attendance fresh read (최대 100건, 202 ops < 500 한도)
      const attRefs = attendanceIds.map((id) => db.collection("attendance").doc(id));
      const attSnaps = await Promise.all(attRefs.map((ref) => tx.get(ref)));

      // [PAY-08] PRECONDITION: 전건 validated
      let freshGross = 0;
      let freshNet   = 0;
      for (const snap of attSnaps) {
        if (!snap.exists) throw new HttpsError("failed-precondition", `출근기록 없음: ${snap.id}`);
        const ad = snap.data()!;
        if (ad.userId !== workerId || ad.businessId !== d.businessId)
          throw new HttpsError("failed-precondition", `소속 불일치: ${snap.id}`);
        if (ad.wageStatus !== "confirmed")
          throw new HttpsError("failed-precondition", `확정(confirmed) 상태가 아닙니다: ${snap.id} (현재: ${ad.wageStatus})`);
        // [PAY-08] 다른 ISR이 이미 lock을 보유 중이면 승인 차단
        const lockedBy = ad.activeInterimSettlementId as string | undefined;
        if (lockedBy && lockedBy !== d.settlementRequestId)
          throw new HttpsError("failed-precondition", `다른 중간정산(${lockedBy})이 이미 해당 출근기록을 보유하고 있습니다: ${snap.id}`);
        // 금액 재계산 (callableRequestInterimSettlement와 동일 formula)
        const finalWage = (ad.finalWage as number | undefined) ?? 0;
        freshGross += finalWage;
        const wageDetail = ad.wageDetail as Record<string, number> | undefined;
        freshNet += wageDetail?.netWage ?? finalWage;
      }

      freshGross = Math.round(freshGross);
      freshNet   = Math.round(freshNet);

      // [PAY-08] ATOMIC WRITE: request 승인 + 금액 재고정 + attendance lock
      tx.update(reqRef, {
        status: "APPROVED",
        approvedBy: callerUid,
        approvedAt: admin.firestore.FieldValue.serverTimestamp(),
        scheduledTransferDate: admin.firestore.Timestamp.fromDate(transferDate),
        requestedAmount: freshGross,
        netAmount: freshNet,
        amountRefreshedAt: admin.firestore.FieldValue.serverTimestamp(),
        ...(d.transferNote ? {transferNote: d.transferNote} : {}),
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      });
      for (const snap of attSnaps) {
        tx.update(snap.ref, {
          activeInterimSettlementId: d.settlementRequestId,
          updatedAt: admin.firestore.FieldValue.serverTimestamp(),
        });
      }
    });

    // 트랜잭션 완료 후 근로자에게 FCM
    if (workerId && savedReqData) {
      const rd = savedReqData as FirebaseFirestore.DocumentData;
      const pStart = (rd.periodStart as admin.firestore.Timestamp).toDate();
      const pEnd   = (rd.periodEnd   as admin.firestore.Timestamp).toDate();
      const periodText =
        `${pStart.getMonth() + 1}/${pStart.getDate()}~${pEnd.getMonth() + 1}/${pEnd.getDate()}`;
      const transferText =
        `${transferDate.getMonth() + 1}/${transferDate.getDate()}`;

      await db.collection("users").doc(workerId).collection("notifications").add({
        userId: workerId,
        type: "interimSettlementApproved",
        title: "중간정산 승인됨",
        body: `[${rd.businessName as string}] ${periodText} 중간정산이 승인되었습니다. ${transferText}에 이체될 예정입니다.`,
        data: {
          businessId: d.businessId,
          settlementRequestId: d.settlementRequestId,
          scheduledTransferDate: transferDate.toISOString(),
          netAmount: String(rd.netAmount ?? 0),
          screen: "interimSettlement",
        },
        isRead: false,
        createdAt: admin.firestore.Timestamp.now(),
      });
    }

    return {success: true};
  }
);

// ══════════════════════════════════════════════════════════════════════════════
// callableProcessInterimSettlement
// 관리자가 APPROVED 상태의 중간정산을 실제 이체 처리한다.
// 단일 트랜잭션: attendance wageStatus → transferred + status → PROCESSED (ATOMICITY-1 해결)
// 완료 후 근로자에게 중간정산 완료 FCM
// ══════════════════════════════════════════════════════════════════════════════
export const callableProcessInterimSettlement = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    const callerUid = request.auth?.uid;
    if (!callerUid) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");

    const d = request.data as {
      settlementRequestId: string;
      businessId: string;
      transferNote?: string;
    };

    if (!d.settlementRequestId) throw new HttpsError("invalid-argument", "settlementRequestId 필수");
    if (!d.businessId) throw new HttpsError("invalid-argument", "businessId 필수");

    const {callerData: processCallerData, bizData: processBizData} = await assertBizAdmin(callerUid, d.businessId);
    // [ISR-APPROVE-PERM] 서브어드민 canManageWage 세부 권한 검증
    const processAdminIds = (processBizData?.adminIds as string[] | undefined) ?? [];
    if (
      (processCallerData?.role as string | undefined) !== "SUPER_ADMIN" &&
      !processAdminIds.includes(callerUid) &&
      (processBizData?.ownerId as string | undefined) !== callerUid
    ) {
      const processMemberSnap = await db.collection("businesses").doc(d.businessId).collection("members").doc(callerUid).get();
      const processPerms = (processMemberSnap.data()?.permissions as Record<string, boolean>) ?? {};
      if (processPerms.canManageWage !== true) throw new HttpsError("permission-denied", "임금 관리 권한이 없습니다.");
    }

    const reqRef = db.collection("interim_settlement_requests").doc(d.settlementRequestId);
    let workerId = "";
    let savedReqData: FirebaseFirestore.DocumentData | null = null;
    let processedCount = 0;

    // [PAY-08] ALL-OR-NOTHING 단일 트랜잭션: 전건 검증 후에만 write
    await db.runTransaction(async (tx) => {
      processedCount = 0; // 재시도 시 초기화

      const reqSnap = await tx.get(reqRef);
      if (!reqSnap.exists) throw new HttpsError("not-found", "중간정산 요청을 찾을 수 없습니다.");

      const rd = reqSnap.data()!;
      if (rd.businessId !== d.businessId)
        throw new HttpsError("permission-denied", "사업장 불일치");
      if (rd.status !== "APPROVED")
        throw new HttpsError("failed-precondition", "APPROVED 상태인 요청만 이체 처리 가능합니다.");

      workerId = rd.workerId as string;
      savedReqData = rd;

      const attendanceIds = Array.isArray(rd.attendanceIds) ? (rd.attendanceIds as string[]) : [];
      if (attendanceIds.length === 0) throw new HttpsError("failed-precondition", "정산 대상 출근기록이 없습니다.");

      const now = admin.firestore.Timestamp.now();
      const noteToWrite = d.transferNote ?? "중간정산 이체";
      const requestId = d.settlementRequestId;

      // [PAY-08] TX 내 attendance fresh read
      const attRefs = attendanceIds.map((id) => db.collection("attendance").doc(id));
      const attSnaps = await Promise.all(attRefs.map((ref) => tx.get(ref)));

      // [PAY-08] PHASE 1: 전건 사전 검증 (write 이전 — all-or-nothing)
      let freshGross = 0;
      let freshNet   = 0;
      for (const snap of attSnaps) {
        if (!snap.exists)
          throw new HttpsError("failed-precondition", `출근기록 없음: ${snap.id}`);
        const ad = snap.data()!;
        if (ad.userId !== workerId || ad.businessId !== d.businessId)
          throw new HttpsError("failed-precondition", `소속 불일치: ${snap.id}`);
        // [PAY-08] lock 소유 확인 — 다른 ISR이 이미 transferred한 경우 충돌 감지
        if (ad.wageStatus === "transferred")
          throw new HttpsError(
            "failed-precondition",
            `해당 출근기록이 다른 경로에서 이미 이체되었습니다: ${snap.id}. 현재 요청을 취소하고 재승인 후 처리해 주세요.`
          );
        if (ad.wageStatus !== "confirmed")
          throw new HttpsError("failed-precondition", `확정(confirmed) 상태가 아닙니다: ${snap.id} (현재: ${ad.wageStatus})`);
        // [PAY-08] lock 검증 — 이 요청의 lock을 소유해야 함
        if (ad.activeInterimSettlementId !== requestId)
          throw new HttpsError(
            "failed-precondition",
            `출근기록의 중간정산 lock이 현재 요청과 일치하지 않습니다: ${snap.id}`
          );
        const finalWage = (ad.finalWage as number | undefined) ?? 0;
        freshGross += finalWage;
        const wageDetail = ad.wageDetail as Record<string, number> | undefined;
        freshNet += wageDetail?.netWage ?? finalWage;
      }

      freshGross = Math.round(freshGross);
      freshNet   = Math.round(freshNet);

      // [PAY-08] AMOUNT DRIFT GUARD — 승인 이후 금액 변경 차단
      if (freshGross !== (rd.requestedAmount as number) || freshNet !== (rd.netAmount as number)) {
        throw new HttpsError(
          "failed-precondition",
          "중간정산 승인 후 급여 금액이 변경되었습니다. 현재 요청을 취소하고 다시 승인해 주세요."
        );
      }

      // [PAY-08] PHASE 2: 전건 통과 후 atomic write
      for (const snap of attSnaps) {
        tx.update(snap.ref, {
          wageStatus: "transferred",
          transferDate: now,
          transferredBy: callerUid,
          transferNote: noteToWrite,
          activeInterimSettlementId: admin.firestore.FieldValue.delete(), // lock 해제
          interimSettlementRequestId: requestId,                          // provenance 영구 보존
          updatedAt: now,
        });
        processedCount++;
      }

      // status → PROCESSED (attendance와 동일 TX — 원자적)
      tx.update(reqRef, {
        status: "PROCESSED",
        processedBy: callerUid,
        processedAt: now,
        ...(d.transferNote ? {transferNote: d.transferNote} : {}),
        updatedAt: now,
      });
    });

    // 완료 FCM (트랜잭션 외부 — 알림 미발송은 치명적 오류 아님)
    if (workerId && savedReqData) {
      const rd = savedReqData as FirebaseFirestore.DocumentData;
      const pStart = (rd.periodStart as admin.firestore.Timestamp).toDate();
      const pEnd   = (rd.periodEnd   as admin.firestore.Timestamp).toDate();
      const periodText =
        `${pStart.getMonth() + 1}/${pStart.getDate()}~${pEnd.getMonth() + 1}/${pEnd.getDate()}`;

      await db.collection("users").doc(workerId).collection("notifications").add({
        userId: workerId,
        type: "wageTransferred",
        category: "personal", // [Phase 2] 근무자에게 발송 → personal
        title: "중간정산 완료",
        body: `[${rd.businessName as string}] ${periodText} 기간 중간정산이 완료되었습니다. 실수령액을 앱에서 확인하세요.`,
        data: {
          businessId: d.businessId,
          settlementRequestId: d.settlementRequestId,
          netAmount: String(rd.netAmount ?? 0),
          screen: "interimSettlement",
        },
        isRead: false,
        createdAt: admin.firestore.Timestamp.now(),
      }).catch((e) => console.error("[callableProcessInterimSettlement] FCM 발송 실패 (무시):", e));
    }

    return {success: true, processedCount};
  }
);

// ─── callableRejectInterimSettlement ─────────────────────────────────────────
// 중간정산 거절 — CF 권한 검증 (callableApproveInterimSettlement 대칭 구현)
// [5C.1-ISR-03] GAP-ISR-01 수정 — 기존 클라이언트 직접 write에서 CF로 이동
// Input : businessId, requestId, rejectReason?
// Output: { success: true }
export const callableRejectInterimSettlement = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    if (!request.auth) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");
    const callerUid = request.auth.uid;

    const {businessId, requestId, rejectReason} = request.data as {
      businessId?: string;
      requestId?: string;
      rejectReason?: string;
    };
    if (!businessId || !requestId) throw new HttpsError("invalid-argument", "businessId, requestId 필수입니다.");

    // [ISR-PERM] callableApproveInterimSettlement과 동일 패턴
    const {callerData: isrRejectCallerData} = await assertBizAdmin(callerUid, businessId);
    const isrRejectCallerRole = isrRejectCallerData?.role as string | undefined;
    if (isrRejectCallerRole !== "BUSINESS_ADMIN" && isrRejectCallerRole !== "SUPER_ADMIN") {
      const memberSnap = await db.collection("businesses").doc(businessId).collection("members").doc(callerUid).get();
      const memberPerms = (memberSnap.data()?.permissions as Record<string, boolean>) ?? {};
      if (memberPerms.canManageWage !== true) throw new HttpsError("permission-denied", "급여 관리 권한이 없습니다.");
    }

    // 1. workerId 사전 조회 (알림 발송용) — 트랜잭션 밖에서 읽어 알림 데이터 확보
    const reqRef = db.collection("interim_settlement_requests").doc(requestId);
    const reqPreSnap = await reqRef.get();
    if (!reqPreSnap.exists) throw new HttpsError("not-found", "중간정산 요청을 찾을 수 없습니다.");
    const reqPreData = reqPreSnap.data()!;
    if (reqPreData.businessId !== businessId) throw new HttpsError("permission-denied", "사업장이 일치하지 않습니다.");
    const workerId = reqPreData.workerId as string;

    const now = admin.firestore.FieldValue.serverTimestamp();

    // 2. 트랜잭션: PENDING → REJECTED (stale reject / 동시 approve+reject 충돌 방어)
    await db.runTransaction(async (tx) => {
      const reqSnap = await tx.get(reqRef);
      const reqData = reqSnap.data()!;
      if (reqData.status !== "PENDING") {
        throw new HttpsError("failed-precondition", `이미 처리된 요청입니다. 현재 상태: ${reqData.status as string}`);
      }
      tx.update(reqRef, {
        status: "REJECTED",
        processedBy: callerUid,
        processedAt: now,
        rejectReason: rejectReason ?? null,
        updatedAt: now,
      });
    });

    // 3. 상태 전이 성공 후 알림 발송 (실패해도 거절 자체에 영향 없음)
    db.collection("users").doc(workerId).collection("notifications").add({
      type: "interimSettlementRejected",
      businessId,
      businessName: reqPreData.businessName ?? null,
      settlementRequestId: requestId,
      periodStart: reqPreData.periodStart ?? null,
      periodEnd: reqPreData.periodEnd ?? null,
      rejectReason: rejectReason ?? null,
      isRead: false,
      createdAt: admin.firestore.Timestamp.now(),
    }).catch((e: unknown) => console.error("[callableRejectInterimSettlement] 알림 발송 실패 (무시):", e));

    return {success: true};
  }
);

// ══════════════════════════════════════════════════════════════════════════════
// callableGetMyInterimSettlements
// 근로자가 자신의 중간정산 요청 목록을 조회한다 (Firestore list 규칙 우회용)
// ══════════════════════════════════════════════════════════════════════════════
export const callableGetMyInterimSettlements = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    const callerUid = request.auth?.uid;
    if (!callerUid) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");

    const d = request.data as {businessId?: string; limit?: number};
    const cap = Math.min(d?.limit ?? 30, 100);

    let query: FirebaseFirestore.Query = db
      .collection("interim_settlement_requests")
      .where("workerId", "==", callerUid)
      .orderBy("createdAt", "desc")
      .limit(cap);

    if (d?.businessId) {
      query = query.where("businessId", "==", d.businessId);
    }

    const snap = await query.get();
    const items = snap.docs.map((doc) => ({id: doc.id, ...doc.data()}));
    return {items};
  }
);

// ─── callableGetPublishedTOs ───────────────────────────────────────────────
// [CF-MIGRATED D6-CP2] tos list isPublished 필터 서버 강제
// Firestore rules list: USER limit<=50 허용 → 미발행 TO 노출 가능 → CF로 이전
// Admin SDK 사용 → rules 우회 + isPublished/status 복합 쿼리 가능
export const callableGetPublishedTOs = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    if (!request.auth) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");
    const {type, city, district} = (request.data ?? {}) as {
      type?: string;
      city?: string;
      district?: string;
    };

    // [index: (isPublished, status, createdAt DESC)] — firestore.indexes.json에 존재
    // isPublished=true인 경우 SCHEDULED는 서버에서 강제 차단되지만,
    // 쿼리 필터를 ACTIVE|FULL로 한정해 이중 방어
    let q: FirebaseFirestore.Query = db.collection("tos")
      .where("isPublished", "==", true)
      .where("status", "in", ["ACTIVE", "FULL"])
      .orderBy("createdAt", "desc");

    // 필터 조합별 인덱스 모두 존재 (단, city+district+type 동시 적용 시 인덱스 없음)
    if (type && !district) q = q.where("type", "==", type);
    if (city) q = q.where("businessCity", "==", city);
    if (city && district) q = q.where("businessDistrict", "==", district);

    q = q.limit(50);
    const snap = await q.get();
    const tos = snap.docs.map((d) => ({id: d.id, ...serializeFirestoreData(d.data())}));
    return {tos};
  }
);

// ─── callableGetPublishedTOsPaged ─────────────────────────────────────────
// [CF-MIGRATED D6-CP2] tos list 페이지네이션 — isPublished 서버 강제
// DocumentSnapshot 커서 → lastToId(String) 커서로 전환
export const callableGetPublishedTOsPaged = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    if (!request.auth) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");
    const {type, city, district, pageSize: rawSize, lastToId} = (request.data ?? {}) as {
      type?: string;
      city?: string;
      district?: string;
      pageSize?: number;
      lastToId?: string;
    };

    const pageSize = Math.min(rawSize ?? 30, 100);

    let q: FirebaseFirestore.Query = db.collection("tos")
      .where("isPublished", "==", true)
      .where("status", "in", ["ACTIVE", "FULL"])
      .orderBy("createdAt", "desc");

    if (type && !district) q = q.where("type", "==", type);
    if (city) q = q.where("businessCity", "==", city);
    if (city && district) q = q.where("businessDistrict", "==", district);

    if (lastToId) {
      const cursorSnap = await db.collection("tos").doc(lastToId).get();
      if (!cursorSnap.exists) {
        return {tos: [], hasMore: false, lastToId: null};
      }
      q = q.startAfter(cursorSnap);
    }

    q = q.limit(pageSize + 1);
    const snap = await q.get();
    const hasMore = snap.docs.length > pageSize;
    const docs = hasMore ? snap.docs.slice(0, pageSize) : snap.docs;
    const tos = docs.map((d) => ({id: d.id, ...serializeFirestoreData(d.data())}));
    const nextLastToId = docs.length > 0 ? docs[docs.length - 1].id : null;

    return {tos, hasMore, lastToId: nextLastToId};
  }
);

// ─── callableRemoveMember ─────────────────────────────────────────────────────
// [CF-MIGRATED] Trust Boundary Charter — subAdminBusinessIds는 _protectedUserFields
// 클라이언트 직접 users/{uid} 쓰기에서 CF로 이전 (member_service.dart removeMember)
// BUSINESS_ADMIN 전용 (CLAUDE.md: 멤버 관리는 SubAdmin 완전 제외)
export const callableRemoveMember = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    if (!request.auth) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");
    const callerUid = request.auth.uid;
    const {businessId, uid} = (request.data ?? {}) as {businessId?: string; uid?: string};
    if (!businessId || typeof businessId !== "string") {
      throw new HttpsError("invalid-argument", "businessId가 필요합니다.");
    }
    if (!uid || typeof uid !== "string") {
      throw new HttpsError("invalid-argument", "uid가 필요합니다.");
    }

    // ── 호출자 권한 확인 (BUSINESS_ADMIN 전용, businesses.adminIds 기반 서버 검증) ──
    // [HIGH-04-FIX 동일 패턴] managedBusinessIds는 클라이언트 오염 가능 → businesses.adminIds 사용
    const [callerSnap, bizSnap] = await Promise.all([
      db.collection("users").doc(callerUid).get(),
      db.collection("businesses").doc(businessId).get(),
    ]);

    if (!bizSnap.exists) throw new HttpsError("not-found", "사업장을 찾을 수 없습니다.");

    const callerRole = callerSnap.data()?.role as string | undefined;
    const isSuperAdmin = callerRole === "SUPER_ADMIN";

    if (!isSuperAdmin) {
      const bizData = bizSnap.data()!;
      const adminIds = (bizData.adminIds as string[] | undefined) ?? [];
      const ownerId = bizData.ownerId as string | undefined;
      if (!adminIds.includes(callerUid) && ownerId !== callerUid) {
        throw new HttpsError("permission-denied", "해당 사업장 관리자만 멤버를 제거할 수 있습니다.");
      }
    }

    // ── 대상 멤버 존재 확인 ──────────────────────────────────────────────────────
    const memberRef = db.collection("businesses").doc(businessId)
      .collection("members").doc(uid);
    if (!(await memberRef.get()).exists) {
      throw new HttpsError("not-found", "해당 멤버를 찾을 수 없습니다.");
    }

    // ── 트랜잭션: 멤버 삭제 + subAdminBusinessIds 서버 제거 ─────────────────────
    const userRef = db.collection("users").doc(uid);
    await db.runTransaction(async (tx) => {
      const userSnap = await tx.get(userRef);
      tx.delete(memberRef);

      const userData = userSnap.data();
      if (!userData) return;

      const subAdminIds = (userData.subAdminBusinessIds as string[] | undefined) ?? [];
      const legacySubAdminOf = userData.subAdminOf as string | undefined;
      const isSubAdminOfThisBiz =
        subAdminIds.includes(businessId) || legacySubAdminOf === businessId;

      if (isSubAdminOfThisBiz) {
        tx.update(userRef, {
          subAdminBusinessIds: admin.firestore.FieldValue.arrayRemove(businessId),
          subAdminOf: admin.firestore.FieldValue.delete(),
        });
      }
    });

    return {success: true};
  }
);

// ── callableLeaveAsSubAdmin ───────────────────────────────────────────────────
// 서브관리자가 특정 사업장에서 스스로 직책 해제 (회원탈퇴 차단 해소 경로)
// Trust Boundary: 타인(businesses/members) + 자신의 _protected 필드 수정 → CF 필수
// Input : { businessId }
// Output: { success }
export const callableLeaveAsSubAdmin = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    if (!request.auth) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");
    const callerUid = request.auth.uid;
    const {businessId} = request.data as {businessId: string};
    if (!businessId) {
      throw new HttpsError("invalid-argument", "businessId가 필요합니다.");
    }

    const userRef  = db.collection("users").doc(callerUid);
    const memberRef = db.collection("businesses").doc(businessId)
                       .collection("members").doc(callerUid);

    await db.runTransaction(async (tx) => {
      const userSnap = await tx.get(userRef);
      if (!userSnap.exists) throw new HttpsError("not-found", "사용자를 찾을 수 없습니다.");

      const subAdminIds = (userSnap.data()?.subAdminBusinessIds ?? []) as string[];
      if (!subAdminIds.includes(businessId)) {
        // 이미 해제된 상태이면 멱등 처리 (에러 없이 성공 반환)
        return;
      }

      // 1. members 서브컬렉션 삭제 (존재하지 않아도 무해)
      const memberSnap = await tx.get(memberRef);
      if (memberSnap.exists) {
        tx.delete(memberRef);
      }

      // 2. users.subAdminBusinessIds 에서 해당 businessId 제거
      tx.update(userRef, {
        subAdminBusinessIds: admin.firestore.FieldValue.arrayRemove(businessId),
      });
    });

    return {success: true};
  }
);

// ── callableCancelTOInvitation ────────────────────────────────────────────────
// 관리자가 발송한 TO 초대를 철회한다. INVITED → CANCELED
// 초대를 보낸 관리자(invitedBy) 또는 사업장 관리자만 취소 가능.
// Input : { applicationId }
// Output: { success }
export const callableCancelTOInvitation = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    if (!request.auth) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");
    const callerUid = request.auth.uid;

    const {applicationId} = request.data as {applicationId: string};
    if (!applicationId || typeof applicationId !== "string") {
      throw new HttpsError("invalid-argument", "applicationId가 필요합니다.");
    }

    const appRef  = db.collection("applications").doc(applicationId);
    const appSnap = await appRef.get();
    if (!appSnap.exists) throw new HttpsError("not-found", "초대를 찾을 수 없습니다.");
    const appData = appSnap.data()!;

    // ── 1. 권한 검증: invitedBy 본인 또는 사업장 관리자 ─────────────────────
    const businessId = appData.businessId as string | undefined;
    const invitedBy  = appData.invitedBy  as string | undefined;
    if (!businessId) throw new HttpsError("internal", "초대 문서에 businessId가 없습니다.");

    // assertBizAdmin으로 관리자 권한 확인 (SUPER_ADMIN 포함 처리됨)
    await assertBizAdmin(callerUid, businessId);

    // ── 2. 상태 검증 ─────────────────────────────────────────────────────────
    const currentStatus = appData.status as string | undefined;
    if (currentStatus === "CANCELED") return {success: true};
    if (currentStatus === "CONFIRMED") {
      throw new HttpsError("failed-precondition", "이미 수락된 초대는 취소할 수 없습니다.");
    }
    if (currentStatus !== "INVITED" && currentStatus !== "EXPIRED") {
      throw new HttpsError("failed-precondition", `취소할 수 없는 상태입니다: ${currentStatus}`);
    }

    // ── 3. INVITED/EXPIRED → CANCELED ────────────────────────────────────────
    // [SYSTEM-INTEGRATION-R2] workDetailCounts 반환.
    //
    //   callableInviteWorker는 INVITED를 만들 때 세 자리를 +1 한다:
    //     slot.pendingCount · TO.totalPending · workDetailCounts[wdId].pendingCount
    //   앞의 둘은 syncTOStats(applications onDocumentWritten)가 count()로 절대값을
    //   다시 써 주므로 여기서 건드리면 이중 감소로 음수가 스쳐 지나간다.
    //   **workDetailCounts는 syncTOStats의 대상이 아니다** — 증감만으로 유지되는
    //   canonical per-wdId counter다. 철회가 이 자리를 되돌리지 않으면
    //   `지원 대기`가 영구히 부풀어 있고, 그 값은 부족 화면의 CTA 강도와
    //   Home의 지원 대기 신호에 그대로 쓰인다.
    //   거절(callableDeclineTOInvitation)은 이미 같은 자리를 -1 한다 —
    //   철회만 빠져 있었다.
    //
    //   EXPIRED는 INVITED를 거쳐서만 도달하므로 같은 카운터를 들고 있다.
    //   상태 전이와 카운터를 한 트랜잭션에 묶어 부분 성공을 막는다.
    const canceledAt = admin.firestore.Timestamp.now();
    const cancelToId = appData.toId as string | undefined;
    const cancelSlotId = appData.slotId as string | undefined;
    const cancelWdId = appData.wdId as string | undefined;
    await db.runTransaction(async (cTx) => {
      const fresh = await cTx.get(appRef);
      const freshStatus = fresh.data()?.status as string | undefined;
      // 그 사이 수락·거절됐다면 카운터는 그 경로가 이미 정리했다.
      if (freshStatus !== "INVITED" && freshStatus !== "EXPIRED") return;

      cTx.update(appRef, {
        status: "CANCELED",
        canceledAt,
        canceledBy: callerUid,
        statusHistory: admin.firestore.FieldValue.arrayUnion({
          status: "CANCELED", at: canceledAt,
          by: callerUid, action: "INVITE_CANCELED",
        }),
      });

      if (cancelToId && cancelSlotId && cancelWdId) {
        cTx.update(
          db.collection("tos").doc(cancelToId)
            .collection("slots").doc(cancelSlotId),
          {
            [`workDetailCounts.${cancelWdId}.pendingCount`]:
              admin.firestore.FieldValue.increment(-1),
          });
      }
    });

    // ── 4. 근로자에게 취소 알림 ─────────────────────────────────────────────
    try {
      const targetUid = appData.uid          as string | undefined;
      const toTitle   = (appData.toTitle     as string | undefined) ?? "";
      const bizName   = (appData.businessName as string | undefined) ?? "";
      if (targetUid) {
        const body = bizName
          ? `${bizName}에서 '${toTitle}' 근무 초대를 취소했습니다.`
          : `'${toTitle}' 근무 초대가 취소되었습니다.`;
        db.collection("users").doc(targetUid).collection("notifications").add({
          userId:    targetUid,
          type:      "toInviteCanceled",
          title:     "초대가 취소되었습니다",
          body,
          data:      {businessId, action: "myApplications"},
          isRead:    false,
          createdAt: admin.firestore.FieldValue.serverTimestamp(),
          readAt:    null,
        }).catch((err) => console.error("[callableCancelTOInvitation] 근로자 알림 실패:", err));
      }
    } catch (_) { /* 알림 실패는 취소 결과에 영향 없음 */ }

    // suppress unused-variable warning
    void invitedBy;
    return {success: true};
  }
);

// ─── callableCancelApprovedInterimSettlement ──────────────────────────────────
// 관리자가 APPROVED 상태의 중간정산을 취소한다 (실제 은행 이체 없이 앱 상태만 해제)
// [PAY-08] attendance-level lock 해제를 위한 공식 취소 경로
// APPROVED → CANCELED + attendance.activeInterimSettlementId 일괄 삭제 (동일 TX)
export const callableCancelApprovedInterimSettlement = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    if (!request.auth) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");
    const callerUid = request.auth.uid;

    const {settlementRequestId, businessId, cancelReason} = request.data as {
      settlementRequestId: string;
      businessId: string;
      cancelReason?: string;
    };

    if (!settlementRequestId) throw new HttpsError("invalid-argument", "settlementRequestId 필수");
    if (!businessId) throw new HttpsError("invalid-argument", "businessId 필수");

    // [ISR-CANCEL-PERM] callableApproveInterimSettlement와 동일 권한
    const {callerData: cancelCallerData, bizData: cancelBizData} = await assertBizAdmin(callerUid, businessId);
    const cancelAdminIds = (cancelBizData?.adminIds as string[] | undefined) ?? [];
    if (
      (cancelCallerData?.role as string | undefined) !== "SUPER_ADMIN" &&
      !cancelAdminIds.includes(callerUid) &&
      (cancelBizData?.ownerId as string | undefined) !== callerUid
    ) {
      const cancelMemberSnap = await db.collection("businesses").doc(businessId).collection("members").doc(callerUid).get();
      const cancelPerms = (cancelMemberSnap.data()?.permissions as Record<string, boolean>) ?? {};
      if (cancelPerms.canManageWage !== true) throw new HttpsError("permission-denied", "임금 관리 권한이 없습니다.");
    }

    const reqRef = db.collection("interim_settlement_requests").doc(settlementRequestId);

    await db.runTransaction(async (tx) => {
      const reqSnap = await tx.get(reqRef);
      if (!reqSnap.exists) throw new HttpsError("not-found", "중간정산 요청을 찾을 수 없습니다.");

      const rd = reqSnap.data()!;
      if (rd.businessId !== businessId)
        throw new HttpsError("permission-denied", "사업장 불일치");
      if (rd.status !== "APPROVED")
        throw new HttpsError("failed-precondition", "APPROVED 상태인 요청만 취소 가능합니다.");

      const attendanceIds = Array.isArray(rd.attendanceIds) ? (rd.attendanceIds as string[]) : [];

      // [PAY-08] TX 내 attendance fresh read — lock 소유 확인
      const attRefs = attendanceIds.map((id) => db.collection("attendance").doc(id));
      const attSnaps = await Promise.all(attRefs.map((ref) => tx.get(ref)));

      for (const snap of attSnaps) {
        if (!snap.exists) continue;
        const ad = snap.data()!;
        // lock 소유 확인 — 이 요청의 lock만 해제 가능
        const lockedBy = ad.activeInterimSettlementId as string | undefined;
        if (lockedBy && lockedBy !== settlementRequestId) {
          throw new HttpsError(
            "failed-precondition",
            `출근기록 ${snap.id}의 lock이 현재 요청과 불일치합니다. (보유: ${lockedBy})`
          );
        }
        if (lockedBy === settlementRequestId) {
          tx.update(snap.ref, {
            activeInterimSettlementId: admin.firestore.FieldValue.delete(),
            updatedAt: admin.firestore.FieldValue.serverTimestamp(),
          });
        }
      }

      // APPROVED → CANCELED
      tx.update(reqRef, {
        status: "CANCELED",
        canceledBy: callerUid,
        canceledAt: admin.firestore.FieldValue.serverTimestamp(),
        ...(cancelReason ? {cancelReason} : {}),
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      });
    });

    return {success: true};
  }
);

// ─── callableAdminDirectInterimSettlement ─────────────────────────────────────
// 관리자가 직접 중간정산을 생성 + 즉시 처리(PROCESSED)하는 CF
// [Trust Boundary] 클라이언트가 interim_settlement_requests 직접 쓰기를 대체
// - 권한: assertBizAdmin 검증 (서브어드민 canManageWage 포함)
// - 원자성: Firestore 트랜잭션으로 attendance 이체 + 요청 문서 생성 동시 처리
// - 멱등: 이미 transferred인 attendance는 건너뜀
export const callableAdminDirectInterimSettlement = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    if (!request.auth) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");
    const callerUid = request.auth.uid;

    const {
      businessId, workerId, workerName, businessName,
      applicationId, attendanceIds, netAmount,
    } = request.data as {
      businessId: string;
      workerId: string;
      workerName: string;
      businessName: string;
      applicationId: string;
      attendanceIds: string[];
      netAmount: number;
    };

    if (!businessId) {
      throw new HttpsError("invalid-argument", "businessId가 필요합니다.");
    }
    if (!workerId)   throw new HttpsError("invalid-argument", "workerId가 필요합니다.");
    if (!applicationId) throw new HttpsError("invalid-argument", "applicationId가 필요합니다.");
    if (!Array.isArray(attendanceIds) || attendanceIds.length === 0) {
      throw new HttpsError("invalid-argument", "attendanceIds가 필요합니다.");
    }
    if (attendanceIds.length > 200) {
      throw new HttpsError("invalid-argument", "최대 200건까지 처리 가능합니다.");
    }

    // 권한 검증
    const {callerData: adminCallerData} = await assertBizAdmin(callerUid, businessId);
    const isSubAdmin = ((adminCallerData?.subAdminBusinessIds ?? []) as string[]).includes(businessId);
    if (isSubAdmin) {
      const memberSnap = await db.collection("businesses").doc(businessId)
        .collection("members").doc(callerUid).get();
      const perms = (memberSnap.data()?.permissions ?? {}) as Record<string, boolean>;
      if (perms.canManageWage !== true) {
        throw new HttpsError("permission-denied", "급여 관리 권한이 없습니다.");
      }
    }

    const now = admin.firestore.FieldValue.serverTimestamp();
    const nowTs = admin.firestore.Timestamp.now();

    // 트랜잭션: attendance fresh read + ISR lock 체크 + 이체 + ISR 문서 생성
    // [PAY-08] TOCTOU 수정: TX 밖 stale read 제거 → TX 안 fresh read + lock 검증
    const settlementRef = db.collection("interim_settlement_requests").doc();

    let actualNetAmount = 0; // TX 내에서 계산, FCM 발송용으로 TX 밖에서 참조

    await db.runTransaction(async (tx) => {
      actualNetAmount = 0; // 재시도 시 초기화

      // [PAY-08] TX 내 attendance fresh read
      const txAttSnaps = await Promise.all(
        attendanceIds.map(id => tx.get(db.collection("attendance").doc(id)))
      );

      const idsToTransfer: string[] = [];
      let periodStart: admin.firestore.Timestamp = nowTs;
      let periodEnd:   admin.firestore.Timestamp = nowTs;
      const dates: admin.firestore.Timestamp[] = [];

      for (const snap of txAttSnaps) {
        if (!snap.exists) continue;
        const ad = snap.data()!;
        if (ad.businessId !== businessId) continue; // 타 사업장 차단
        if (ad.userId !== workerId) continue;         // 타 근로자 차단

        const ws = ad.wageStatus as string | undefined;

        // [PAY-08] 중간정산 APPROVED lock — 관리자 직접 정산도 차단
        if (ad.activeInterimSettlementId) continue; // lock 보유 중 — skip

        if (ws === "transferred") {
          // 이미 이체된 건 — 금액 합산만 (멱등)
          actualNetAmount += ((ad.finalWage as number | undefined) ?? 0);
          continue;
        }
        if (ws !== "confirmed") continue;

        idsToTransfer.push(snap.id);
        actualNetAmount += ((ad.finalWage as number | undefined) ?? 0);
        const wd = ad.workDate as admin.firestore.Timestamp | undefined;
        if (wd) dates.push(wd);
      }

      if (idsToTransfer.length === 0) {
        throw new HttpsError("failed-precondition", "이체 가능한 출근기록이 없습니다. (모두 이체 완료이거나 중간정산 진행 중)");
      }

      if (dates.length > 0) {
        dates.sort((a, b) => a.seconds - b.seconds);
        periodStart = dates[0];
        periodEnd   = dates[dates.length - 1];
      }

      // attendance 이체 + provenance 기록
      for (const id of idsToTransfer) {
        const ref = db.collection("attendance").doc(id);
        tx.update(ref, {
          wageStatus:               "transferred",
          transferDate:             now,
          transferredBy:            callerUid,
          updatedAt:                now,
          transferNote:             "중간정산 이체",
          interimSettlementRequestId: settlementRef.id, // [PAY-08] provenance
          cancelNote:               admin.firestore.FieldValue.delete(),
          cancelledTransferAt:      admin.firestore.FieldValue.delete(),
          cancelledTransferBy:      admin.firestore.FieldValue.delete(),
        });
      }

      // interim_settlement_requests 문서 생성 (PROCESSED 상태로 직접 기록)
      tx.set(settlementRef, {
        businessId,
        businessName:    businessName ?? "",
        workerId,
        workerName:      workerName ?? "",
        applicationId,
        attendanceIds,
        requestedAmount: netAmount ?? actualNetAmount,
        netAmount:       actualNetAmount,
        requestReason:   "관리자 중간정산 처리",
        status:          "PROCESSED",
        createdAt:       now,
        processedAt:     now,
        processedBy:     callerUid,
        transferNote:    "중간정산 이체",
        periodStart,
        periodEnd,
      });
    });

    // FCM 알림 (실패해도 이체에 영향 없음)
    try {
      if (actualNetAmount > 0) {
        await db.collection("users").doc(workerId).collection("notifications").add({
          userId:   workerId,
          type:     "interimSettlementCompleted",
          category: "personal", // [Phase 2] 근무자에게 발송 → personal
          title:    "중간정산이 완료되었습니다",
          body:     `[${businessName ?? ""}] 중간정산 ${actualNetAmount.toLocaleString()}원이 처리되었습니다.`,
          isRead:   false,
          data: {
            businessId,
            screen: "interimSettlement",
            settlementRequestId: settlementRef.id,
          },
          createdAt: now,
          readAt:    null,
        });
      }
    } catch (e) {
      console.error("[callableAdminDirectInterimSettlement] 알림 발송 실패:", e);
    }

    return {success: true, settlementId: settlementRef.id, netAmount: actualNetAmount};
  }
);

// ─── callableRecalcToTotalRequired ────────────────────────────────────────────
// 슬롯 totalRequired 필드 합산으로 TO.totalRequired를 서버에서 재계산
// [Trust Boundary] 클라이언트 FieldValue.increment(delta) 경합 조건 대체
// - 슬롯 수천 건에 대응: 499건 페이지네이션
// - 원자성: 최종 합산값만 TO 문서에 1회 업데이트
export const callableRecalcToTotalRequired = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    if (!request.auth) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");
    const callerUid = request.auth.uid;

    const {businessId, toId} = request.data as {businessId: string; toId: string};

    if (!businessId) {
      throw new HttpsError("invalid-argument", "businessId가 필요합니다.");
    }
    if (!toId)       throw new HttpsError("invalid-argument", "toId가 필요합니다.");

    // 권한 검증
    await assertBizAdmin(callerUid, businessId);

    // TO 소속 검증
    const toSnap = await db.collection("tos").doc(toId).get();
    if (!toSnap.exists) throw new HttpsError("not-found", "공고를 찾을 수 없습니다.");
    if (toSnap.data()?.businessId !== businessId) {
      throw new HttpsError("permission-denied", "해당 공고에 대한 권한이 없습니다.");
    }

    // 슬롯 전체 순회 — 499건 페이지네이션
    let totalRequired = 0;
    let lastSlot: FirebaseFirestore.DocumentSnapshot | undefined;
    while (true) {
      let q: FirebaseFirestore.Query = db
        .collection("tos").doc(toId).collection("slots")
        .limit(499);
      if (lastSlot) q = q.startAfter(lastSlot);
      const pageSnap = await q.get();
      if (pageSnap.empty) break;
      for (const doc of pageSnap.docs) {
        totalRequired += ((doc.data().totalRequired as number | undefined) ?? 0);
      }
      if (pageSnap.size < 499) break;
      lastSlot = pageSnap.docs[pageSnap.docs.length - 1];
    }

    // TO.totalRequired 업데이트
    await db.collection("tos").doc(toId).update({
      totalRequired,
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    });

    return {success: true, totalRequired};
  }
);

// ═══════════════════════════════════════════════════════════
// 🔒 [SEC-FIX 2026-08-10] callableGetWorkerBasicProfile
//    관리자/서브관리자가 계약서 작성 등을 위해 근무자 기본 정보 조회
//    - assertBizAdmin(callerUid, businessId) 검증 (BUSINESS_ADMIN + SubAdmin 포함)
//    - 해당 근무자가 해당 사업장의 지원자인지 applications 컬렉션으로 재검증
//    - 민감 필드(residentNumber, ci, foreignIdNumber, accountNumber) 제외하고 반환
// ═══════════════════════════════════════════════════════════
export const callableGetWorkerBasicProfile = onCall(
  {region: "asia-northeast3"},
  async (request) => {
    if (!request.auth) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");
    const callerUid = request.auth.uid;
    const {workerUid, businessId} = request.data as {workerUid?: string; businessId?: string};

    if (!workerUid || !businessId) {
      throw new HttpsError("invalid-argument", "workerUid, businessId가 필요합니다.");
    }

    // 1. 권한 검증 — BUSINESS_ADMIN(ownerId/adminIds) + SubAdmin(subAdminBusinessIds) 모두 허용
    await assertBizAdmin(callerUid, businessId);

    // 2. 해당 근무자가 해당 사업장 지원자인지 확인 (applications 컬렉션)
    const appSnap = await db
      .collection("applications")
      .where("uid", "==", workerUid)
      .where("businessId", "==", businessId)
      .limit(1)
      .get();

    if (appSnap.empty) {
      throw new HttpsError(
        "permission-denied",
        "해당 사업장의 지원자 정보에 접근할 권한이 없습니다."
      );
    }

    // 3. 민감 필드 제외한 기본 정보만 반환
    const workerDoc = await db.collection("users").doc(workerUid).get();
    if (!workerDoc.exists) {
      throw new HttpsError("not-found", "근무자 정보를 찾을 수 없습니다.");
    }

    const wd = workerDoc.data()!;
    const birthDateTs = wd["birthDate"] as admin.firestore.Timestamp | undefined;

    return {
      name:          (wd["name"]          as string | undefined) ?? null,
      // [BUG-AUTH-11 FIX] contactPhone ?? authPhone ?? phone — 신규 가입자 전화번호 누락 방지
      phone:         ((wd["contactPhone"] ?? wd["authPhone"] ?? wd["phone"]) as string | undefined) ?? null,
      birthDateMs:   birthDateTs ? birthDateTs.toMillis() : null,
      address:       (wd["address"]       as string | undefined) ?? null,
      detailAddress: (wd["detailAddress"] as string | undefined) ?? null,
    };
  }
);

// ═══════════════════════════════════════════════════════════
// callableMigrateUserWorkHours
//
// 목적: totalWorkHours가 0으로 잘못 집계된 사용자 데이터 복구
//
// 원인: onAttendanceWageStatusChanged 트리거가 attendance.workHours(최상위 필드)를
//   읽는데, callableCalculateAndConfirmWage는 이 필드를 쓰지 않아
//   wageStatus 확정 시 workHours=undefined → 0 폴백 → totalWorkHours에 0이 누적됨.
//
// 마이그레이션 방식:
//   wageStatus가 'confirmed' 또는 'transferred'인 attendance 문서 전수 조회 →
//   workHours(최상위) 우선, 없으면 wageDetail.workMinutes / 60 fallback →
//   userId별 합산 → users 문서 totalWorkHours 일괄 덮어쓰기.
//
// 주의:
//   - totalWorkDays는 트리거가 (workHours 무관하게) 정상 집계하므로 건드리지 않는다.
//   - 노쇼(NO_SHOW) · 결근(absent)은 실제 근무가 아니므로 제외한다.
//   - SUPER_ADMIN 전용, 일회성 실행.
// ═══════════════════════════════════════════════════════════
export const callableMigrateUserWorkHours = onCall(
  { region: "asia-northeast3" },
  async (request) => {
    // SUPER_ADMIN 전용
    const callerUid = request.auth?.uid;
    if (!callerUid) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");
    const callerDoc = await db.collection("users").doc(callerUid).get();
    if (callerDoc.data()?.role !== "SUPER_ADMIN") {
      throw new HttpsError("permission-denied", "슈퍼 어드민만 실행할 수 있습니다.");
    }

    // 1. wageStatus in ['confirmed', 'transferred'] 전체 attendance 조회
    const snap = await db.collection("attendance")
      .where("wageStatus", "in", ["confirmed", "transferred"])
      .get();

    // 2. userId별 workHours 합산 + workTypeStats 집계
    //    workHours(최상위) 없으면 wageDetail.workMinutes / 60 fallback
    const userHoursMap = new Map<string, number>();
    // userId → workType → 근무일수
    const userWorkTypeMap = new Map<string, Map<string, number>>();

    for (const doc of snap.docs) {
      const data = doc.data();
      // [BUG-FIX] uid → userId (AttendanceModel.toMap() 실제 필드명)
      const userId = data["userId"] as string | undefined;
      const docStatus = (data["status"] as string | undefined) ?? "";

      // 노쇼·결근은 실제 근무가 아니므로 제외 (트리거와 동일 조건)
      if (!userId || docStatus === "NO_SHOW" || docStatus === "absent") continue;

      // --- totalWorkHours 합산 ---
      const rawWorkHours = data["workHours"] as number | undefined;
      const wdWorkMinutes =
        (data["wageDetail"] as Record<string, unknown> | undefined)
          ?.workMinutes as number | undefined;

      const hours =
        rawWorkHours != null
          ? Math.round(rawWorkHours)
          : wdWorkMinutes != null
            ? Math.round(wdWorkMinutes / 60)
            : 0;

      userHoursMap.set(userId, (userHoursMap.get(userId) ?? 0) + hours);

      // --- workTypeStats 집계 ---
      const workType = data["workType"] as string | undefined;
      if (workType) {
        if (!userWorkTypeMap.has(userId)) {
          userWorkTypeMap.set(userId, new Map<string, number>());
        }
        const typeMap = userWorkTypeMap.get(userId)!;
        typeMap.set(workType, (typeMap.get(workType) ?? 0) + 1);
      }
    }

    // 3. users 문서 일괄 업데이트 (Firestore batch 최대 500건)
    //    totalWorkHours + workTypeStats 동시 복구
    const allUserIds = Array.from(
      new Set([
        ...Array.from(userHoursMap.keys()),
        ...Array.from(userWorkTypeMap.keys()),
      ])
    );
    const BATCH_SIZE = 400;
    let updatedCount = 0;

    for (let i = 0; i < allUserIds.length; i += BATCH_SIZE) {
      const batch = db.batch();
      for (const uid of allUserIds.slice(i, i + BATCH_SIZE)) {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const updateData: Record<string, any> = {};

        // totalWorkHours 복구
        if (userHoursMap.has(uid)) {
          updateData["totalWorkHours"] = userHoursMap.get(uid) ?? 0;
        }

        // workTypeStats 복구 — 확정된 attendance 전체 재집계로 덮어쓰기
        const typeMap = userWorkTypeMap.get(uid);
        if (typeMap) {
          for (const [wt, count] of typeMap.entries()) {
            updateData[`workTypeStats.${wt}`] = count;
          }
        }

        if (Object.keys(updateData).length > 0) {
          batch.update(db.collection("users").doc(uid), updateData);
          updatedCount++;
        }
      }
      await batch.commit();
    }

    console.log(
      `✅ [callableMigrateUserWorkHours] 완료: ${updatedCount}명 업데이트, ` +
      `대상 attendance ${snap.size}건`
    );
    return {
      updatedUsers: updatedCount,
      scannedAttendances: snap.size,
    };
  }
);

// ═══════════════════════════════════════════════════════════════════════════════
// PHASE 1 — Admin Home Summary Data Layer
// callableGetAdminHomeSummary + private server helpers
// client-supplied businessIds 신뢰 금지 — auth uid 기반 scope 서버 결정
// ═══════════════════════════════════════════════════════════════════════════════

// ─── KST 날짜 유틸 ───────────────────────────────────────────────────────────

/** KST 오늘 자정을 UTC 기준 Date로 반환 */
function srvHomeKSTMidnight(): Date {
  const KST_MS = 9 * 60 * 60 * 1000;
  const kst = new Date(Date.now() + KST_MS);
  return new Date(
    Date.UTC(kst.getUTCFullYear(), kst.getUTCMonth(), kst.getUTCDate()) - KST_MS
  );
}

/** UTC Date → YYYYMMDD 문자열 (KST 기준, attendance doc ID용) */
function srvHomeDateStr(utcDate: Date): string {
  const KST_MS = 9 * 60 * 60 * 1000;
  const kst = new Date(utcDate.getTime() + KST_MS);
  return (
    String(kst.getUTCFullYear()) +
    String(kst.getUTCMonth() + 1).padStart(2, "0") +
    String(kst.getUTCDate()).padStart(2, "0")
  );
}

/** UTC Date → YYYY-MM-DD 레이블 (KST 기준, oldestDate 리포팅용) */
function srvHomeDateLabel(utcDate: Date): string {
  const s = srvHomeDateStr(utcDate);
  return `${s.slice(0, 4)}-${s.slice(4, 6)}-${s.slice(6, 8)}`;
}

// ─── Section 헬퍼: Approval (PENDING 지원서) ─────────────────────────────────

async function srvHomeApproval(
  bizId: string,
  todayMs: number
): Promise<{total: number; overdue: number}> {
  const snap = await db.collection("applications")
    .where("businessId", "==", bizId)
    .where("status", "==", "PENDING")
    .select("workDate")
    .get();
  let total = 0, overdue = 0;
  for (const doc of snap.docs) {
    total++;
    const d = doc.data();
    // [AH-V2-04C.1] overdue = workDate < KST 오늘 자정. type 조건 없음.
    //   장기(long_term) 지원서의 workDate는 계약 시작일이므로, 그날이 지났는데
    //   아직 PENDING이면 단기와 똑같이 방치된 요청이다.
    //   total은 이미 단기+장기 전체이고 SupportReviewQueue도 그렇다([PHASE-2A]).
    //   overdue만 short로 좁아 있어 Home 배지와 Queue '기한 지남'이 어긋났다.
    const wdTs = d["workDate"] as admin.firestore.Timestamp | undefined;
    if (wdTs && wdTs.toMillis() < todayMs) overdue++;
  }
  return {total, overdue};
}

// ─── 계약 의무 canonical ─────────────────────────────────────────────────────
//
// [PREDEVICE-CONTRACT-OBLIGATION]
//   Application commitment state ≠ Contract lifecycle state.
//   좌석을 확정받은 사람(CONTRACT_PENDING 또는 CONFIRMED)은 근로계약서를
//   받아야 한다. 어떤 경로로 그 좌석에 도달했는지는 상관없다 — 지원 승인이든
//   초대 수락이든 자동연장이든 의무는 같다. 그래서 status 하나로 판단하지 않고
//   "좌석 있음 + 아직 유효한 계약서가 발송되지 않음"으로 판단한다.
//
//   이전 구현은 status === "CONTRACT_PENDING"만 셌다. callableAcceptTOInvitation은
//   INVITED → CONFIRMED로 바로 가므로, 초대를 수락한 근로자는 계약서 없이
//   확정되고도 홈에도 계약 관리 화면에도 나타나지 않았다.

/** 좌석을 차지하는(= 계약서를 받아야 하는) application 상태. */
const CONTRACT_SEAT_STATUSES = ["CONTRACT_PENDING", "CONFIRMED"];

/** 고용관계가 이미 끝나 계약서 발송이 더 이상 행동이 아닌 경우. */
const CONTRACT_ENDED_STATUSES = ["APPROVED", "AUTO_APPROVED"];

/**
 * 계약서 상태 → 아직 근로자에게 전달되지 않았는가.
 *
 * pending_employer는 사업주 처리 대기다 — 문서는 있어도 근로자는 받지 못했다.
 * pending_worker부터가 "발송됨"이다.
 *
 * @param {string|undefined} status employment_contracts.status
 * @return {boolean} 근로자에게 아직 전달되지 않았으면 true
 */
function srvContractNotIssuedYet(status: string | undefined): boolean {
  if (!status) return true;
  return status === "voided" ||
    status === "pending_employer" ||
    status === "draft";
}

/**
 * application 하나에 대해 유효한 계약서가 발송됐는지 판정.
 *
 * linking rule은 2단계다 — 계약해지 정리 경로가 이미 쓰는 것과 같다.
 *   1) applicationId == appId          (단건/번들 1차)
 *   2) applicationIds array-contains   (번들 2차 — _addSlot이 여기에만 쓴다)
 * 1단계만 보면 번들 2차 지원서는 계약서가 있는데도 미발송으로 잡힌다.
 *
 * @param {string} appId 지원서 문서 ID
 * @param {string} bizId 사업장 ID — 타 사업장 계약서 오매칭 차단
 * @return {Promise<boolean>} 근로자에게 전달된 계약서가 있으면 true
 */
async function srvContractIssuedFor(
  appId: string,
  bizId: string
): Promise<boolean> {
  return srvIssuedContractExists(appId, bizId);
}

/**
 * srvContractIssuedFor와 같은 판정을 트랜잭션 안에서도 수행한다.
 *
 * 미발송 집계(홈·계약탭)와 발송 차단이 같은 식을 써야 한다 —
 * 집계가 "발송됨"이라고 본 지원서에 계약서가 한 장 더 생기면 안 된다.
 *
 * @param {string} appId 지원서 문서 ID
 * @param {string} bizId 사업장 ID — 타 사업장 계약서 오매칭 차단
 * @param {FirebaseFirestore.Transaction|undefined} tx 있으면 트랜잭션 읽기
 * @return {Promise<boolean>} 근로자에게 전달된 계약서가 있으면 true
 */
async function srvIssuedContractExists(
  appId: string,
  bizId: string,
  tx?: FirebaseFirestore.Transaction
): Promise<boolean> {
  const run = (q: FirebaseFirestore.Query) => (tx ? tx.get(q) : q.get());
  const base = db.collection("employment_contracts")
    .where("businessId", "==", bizId);
  const byId = await run(
    base.where("applicationId", "==", appId).select("status").limit(5));
  let docs = byId.docs;
  if (docs.length === 0) {
    const byArray = await run(
      base.where("applicationIds", "array-contains", appId)
        .select("status").limit(5));
    docs = byArray.docs;
  }
  // 한 건이라도 근로자에게 전달된 계약서가 있으면 의무는 이행된 것으로 본다.
  return docs.some(
    (d) => !srvContractNotIssuedYet(d.data()["status"] as string | undefined)
  );
}

/**
 * 좌석은 있으나 계약서가 아직 발송되지 않았는가.
 *
 * 홈(srvHomeUnsentContract)과 계약 관리 화면
 * (callableGetUnsentApplicationsByBiz)이 함께 쓰는 단일 정책이다.
 * 두 화면이 서로 다른 숫자를 말하지 않도록 사본을 만들지 않는다.
 *
 * @param {string} appId 지원서 문서 ID
 * @param {admin.firestore.DocumentData} appData 지원서 데이터
 * @param {string} bizId 사업장 ID
 * @return {Promise<boolean>} 계약 미발송이면 true
 */
async function srvNeedsContractIssue(
  appId: string,
  appData: admin.firestore.DocumentData,
  bizId: string
): Promise<boolean> {
  const st = (appData["status"] as string) ?? "";
  if (!CONTRACT_SEAT_STATUSES.includes(st)) return false;
  // 좌석이 반납된 자리(NO_SHOW 대체충원 등)는 발송 대상이 아니다.
  if (appData["staffingReleasedAt"] != null) return false;
  // 퇴사·해지가 승인된 관계는 지금 계약서를 보내는 것이 행동이 아니다.
  const term = (appData["terminationStatus"] as string) ?? "";
  const resign = (appData["resignStatus"] as string) ?? "";
  if (CONTRACT_ENDED_STATUSES.includes(term)) return false;
  if (CONTRACT_ENDED_STATUSES.includes(resign)) return false;
  return !(await srvContractIssuedFor(appId, bizId));
}

// ─── Section 헬퍼: Unsent Contract (미발송 계약서) ───────────────────────────

async function srvHomeUnsentContract(bizId: string): Promise<{count: number}> {
  // 좌석 보유 지원서 전체를 페이지네이션으로 순회 — 200건 단순 limit으로 인한
  // 무음 undercount(계약서 미확인 건 누락) 방지
  const PAGE_SIZE = 200;
  const MAX_PAGES = 25; // 최대 5,000건 — 초과 시 count 보장 불가 → throw
  let count = 0;
  let cursor: admin.firestore.QueryDocumentSnapshot | undefined;
  let exhausted = false;
  const CHUNK = 20;

  for (let page = 0; page < MAX_PAGES; page++) {
    // [PREDEVICE-UNSENT-ORDERBY] orderBy를 쓰지 않는다.
    //   이전 구현은 orderBy("createdAt","desc")로 페이징했는데 applications에는
    //   createdAt 필드가 없다(canonical은 appliedAt). Firestore는 정렬 필드가
    //   없는 문서를 결과에서 제외하므로 이 쿼리는 언제나 0건이었고, 홈의
    //   "계약 미발송"은 available:true인 채로 항상 0을 표시해 왔다.
    //   실패가 아니라 성공한 0으로 보였다는 점이 이 버그의 핵심이다.
    //   appliedAt으로 바꾸려면 새 복합 인덱스가 필요하다. 정렬 없이도
    //   Firestore는 __name__ 순서를 암묵 적용하고 startAfter가 그대로 동작하므로
    //   인덱스를 늘리지 않고 전수를 보장할 수 있다. 이 카운트에 순서는 무의미하다.
    // srvNeedsContractIssue가 읽는 필드만 select — 문서 전체를 받지 않는다.
    let q: admin.firestore.Query = db.collection("applications")
      .where("businessId", "==", bizId)
      .where("status", "in", CONTRACT_SEAT_STATUSES)
      .select("status", "staffingReleasedAt",
        "terminationStatus", "resignStatus")
      .limit(PAGE_SIZE);
    if (cursor) q = q.startAfter(cursor);

    const appSnap = await q.get();
    if (appSnap.empty) { exhausted = true; break; }

    // employment_contracts 존재 여부 확인 (20개씩 병렬)
    for (let i = 0; i < appSnap.docs.length; i += CHUNK) {
      const chunk = appSnap.docs.slice(i, i + CHUNK);
      // 정책은 srvNeedsContractIssue 한 곳에만 있다 — 화면별 사본을 만들지 않는다.
      const needs = await Promise.all(
        chunk.map((d) => srvNeedsContractIssue(d.id, d.data(), bizId))
      );
      for (const n of needs) if (n) count++;
    }

    if (appSnap.docs.length < PAGE_SIZE) { exhausted = true; break; }
    cursor = appSnap.docs[appSnap.docs.length - 1];
  }

  // cap 초과: 마지막 페이지가 꽉 찬 채로 루프 종료 → 잔여 건 미확인 → 거짓 count 반환 금지
  if (!exhausted) {
    throw new Error(
      `[unsentContract] ${bizId} 좌석 보유 지원서가 상한(${MAX_PAGES * PAGE_SIZE})을 초과합니다.`
    );
  }

  return {count};
}

// ─── Section 헬퍼: Unpaid Wage (급여 미이체) ─────────────────────────────────

async function srvHomeUnpaidWage(
  bizId: string,
  todayMs: number
): Promise<{count: number; overdue: number; missingDueDate: number}> {
  // canonical unit: businessId × userId × paymentDueDate
  // [HOME-WAGE-01] paymentDueDate는 attendance 문서의 top-level 필드.
  // wageDetail 내부에 없음 — wageDetail은 임금 상세(시급/공제 등) 전용.
  // AttendanceModel.toMap(): 'paymentDueDate': Timestamp.fromDate(paymentDueDate!)
  const snap = await db.collection("attendance")
    .where("businessId", "==", bizId)
    .where("wageStatus", "==", "confirmed")
    // [AH-V2-05B.2] status/finalWage는 terminal non-payable 판별용 — 추가 쿼리 없음
    .select("userId", "paymentDueDate", "status", "finalWage")
    .get();

  const groups = new Map<string, number>(); // groupKey → dueDate millis
  // [PHASE-2C.2] missingDueDate canonical unit: businessId × userId (unique userId 수)
  // Payroll _getPendingGroupsAll()의 userId::no_date 카드 단위와 동일
  const missingUserIds = new Set<string>();

  for (const doc of snap.docs) {
    const d = doc.data();
    const uid = (d["userId"] as string | undefined) ?? "";
    // [HOME-WAGE-01] top-level 필드에서 직접 읽기 (wageDetail 내부 아님)
    const pdTs = d["paymentDueDate"] as admin.firestore.Timestamp | undefined;
    if (!pdTs) {
      // [AH-V2-05B.2] 노쇼·결근은 지급할 임금이 없는 종결 상태다.
      //   자동결근/자동노쇼(단기·장기)/수동노쇼 다섯 경로 모두
      //   status + finalWage:0 + wageStatus:"confirmed"를 쓰고 paymentDueDate를 쓰지
      //   않으므로, 그대로 두면 '지급일 확인 필요'에 영구히 남아 줄지 않는다.
      //   review_request 트리거도 같은 조건으로 이들을 "실제 근무 없음"으로 제외한다.
      //
      //   확실한 false positive만 제거한다 — status를 알 수 없거나 finalWage가
      //   0이 아닌 문서는 계속 포함해 관리자가 확인하게 둔다.
      const st = d["status"] as string | undefined;
      const fw = (d["finalWage"] as number | undefined) ?? 0;
      const nonPayable = (st === "NO_SHOW" || st === "absent") && fw === 0;
      if (nonPayable) continue;
      missingUserIds.add(uid); // doc-count 아님 — unique userId 집계
      continue;
    }
    const key = `${uid}_${srvHomeDateStr(pdTs.toDate())}`;
    if (!groups.has(key)) groups.set(key, pdTs.toMillis());
  }

  let overdue = 0;
  for (const ms of groups.values()) {
    if (ms < todayMs) overdue++;
  }
  return {count: groups.size, overdue, missingDueDate: missingUserIds.size};
}

// ─── Section 헬퍼: Unclosed (마감 미처리) ────────────────────────────────────

async function srvHomeUnclosed(
  bizId: string,
  todayKSTMidnight: Date
): Promise<{count: number; oldestDate: string | null}> {
  const KST_MS = 9 * 60 * 60 * 1000;
  const DAY_MS = 24 * 60 * 60 * 1000;
  const todayMs = todayKSTMidnight.getTime();
  const yesterdayMidnight = new Date(todayMs - DAY_MS);
  const KR_DAYS = ["일", "월", "화", "수", "목", "금", "토"];

  // 1. 활성 지원서 조회 (CONFIRMED + CONTRACT_PENDING)
  const appSnap = await db.collection("applications")
    .where("businessId", "==", bizId)
    .where("status", "in", ["CONFIRMED", "CONTRACT_PENDING"])
    .select("type", "workDate", "workEndDate", "desiredStartDate",
            "actualResignDate", "workDays", "leaveDates", "extraWorkDates")
    .get();
  if (appSnap.empty) return {count: 0, oldestDate: null};

  // 2. 예상 근무일 (appId, dateUtc) 페어 수집
  // docDateMap: attendance doc ID → KST 자정 UTC Date
  const docDateMap = new Map<string, Date>();

  for (const appDoc of appSnap.docs) {
    const d = appDoc.data();
    const appId = appDoc.id;
    const isLong = d["type"] === "long_term";

    if (!isLong) {
      // 단기: 단일 workDate
      const wdTs = d["workDate"] as admin.firestore.Timestamp | undefined;
      if (!wdTs || wdTs.toMillis() >= todayMs) continue;
      const kst = new Date(wdTs.toMillis() + KST_MS);
      const midnight = new Date(
        Date.UTC(kst.getUTCFullYear(), kst.getUTCMonth(), kst.getUTCDate()) - KST_MS
      );
      const docId = `${appId}_${srvHomeDateStr(midnight)}`;
      if (!docDateMap.has(docId)) docDateMap.set(docId, midnight);
    } else {
      // 장기: 날짜 범위 펼치기
      const startTs = (d["desiredStartDate"] ?? d["workDate"]) as admin.firestore.Timestamp | undefined;
      const endTs   = (d["actualResignDate"] ?? d["workEndDate"]) as admin.firestore.Timestamp | undefined;
      // [PHASE-2B.1] open-ended(endTs==null) → yesterdayMidnight까지 확장
      // (getUnclosedDaysCount Flutter 동일 semantics: endOnly==null → yesterdayOnly까지 loop)
      // endTs == null AND isTerminationApproved 근로자는 applications 쿼리에서 제외됨
      // (status가 RESIGNED 등으로 전환되어 CONFIRMED/CONTRACT_PENDING 아님)
      if (!startTs) continue;

      const startKST = new Date(startTs.toMillis() + KST_MS);
      let current = new Date(
        Date.UTC(startKST.getUTCFullYear(), startKST.getUTCMonth(), startKST.getUTCDate()) - KST_MS
      );
      const actualEndMs = endTs
        ? Math.min(endTs.toMillis(), yesterdayMidnight.getTime())
        : yesterdayMidnight.getTime(); // open-ended: 어제까지
      if (current.getTime() > actualEndMs) continue;

      const workDays   = (d["workDays"]       as string[] | undefined) ?? [];
      const leaveDates = (d["leaveDates"]     as admin.firestore.Timestamp[] | undefined) ?? [];
      const extraDates = (d["extraWorkDates"] as admin.firestore.Timestamp[] | undefined) ?? [];

      // Safety cap: 3650일(≈10년) — 이 이상이면 데이터 신뢰 불가
      // cap 도달 시 throw → available:false 반환 (silent undercount 금지)
      const CAP_DAYS = 3650;
      let safety = 0;
      while (current.getTime() <= actualEndMs) {
        if (safety >= CAP_DAYS) {
          // 신뢰 불가 → caller에서 available:false 처리
          throw new Error(
            `[unclosed] ${bizId}/${appId} 날짜 범위가 ${CAP_DAYS}일을 초과합니다. ` +
            `startDate=${startTs.toDate().toISOString()} actualEnd=${new Date(actualEndMs).toISOString()}`
          );
        }
        safety++;
        const nextDay = new Date(current.getTime() + DAY_MS);
        const weekday = KR_DAYS[new Date(current.getTime() + KST_MS).getUTCDay()];
        const curMs   = current.getTime();
        const nextMs  = nextDay.getTime();

        const isWorkDay = workDays.includes(weekday);
        const isExtra   = extraDates.some((ts) => {
          const m = ts.toMillis(); return m >= curMs && m < nextMs;
        });
        const isLeave   = leaveDates.some((ts) => {
          const m = ts.toMillis(); return m >= curMs && m < nextMs;
        });

        if (!isLeave && (isWorkDay || isExtra)) {
          const docId = `${appId}_${srvHomeDateStr(current)}`;
          if (!docDateMap.has(docId)) docDateMap.set(docId, new Date(current));
        }
        current = nextDay;
      }
    }
  }

  if (docDateMap.size === 0) return {count: 0, oldestDate: null};

  // 3. attendance 배치 읽기 (400개씩 — Admin SDK 안전 한도)
  const refs = [...docDateMap.keys()].map((id) => db.collection("attendance").doc(id));
  const closedSet = new Set<string>();

  const BATCH = 400;
  for (let i = 0; i < refs.length; i += BATCH) {
    const snaps = await db.getAll(...refs.slice(i, i + BATCH));
    for (const snap of snaps) {
      if (!snap.exists) continue;
      const sd = snap.data()!;
      const ws = (sd["wageStatus"] as string) ?? "";
      const st = (sd["status"]    as string) ?? "";
      if (ws === "confirmed" || ws === "transferred" || st === "NO_SHOW") {
        closedSet.add(snap.id);
      }
    }
  }

  // 4. unclosed date 집계 (canonical unit: unique date label)
  const unclosedDates = new Set<string>();
  let oldestUtc: Date | null = null;

  for (const [docId, dateUtc] of docDateMap) {
    if (!closedSet.has(docId)) {
      unclosedDates.add(srvHomeDateLabel(dateUtc));
      if (!oldestUtc || dateUtc.getTime() < oldestUtc.getTime()) oldestUtc = dateUtc;
    }
  }

  return {
    count: unclosedDates.size,
    oldestDate: oldestUtc ? srvHomeDateLabel(oldestUtc) : null,
  };
}

// ─── Unclosed Queue 헬퍼: 단일 사업장의 미마감 business×date rows ──────────────
//
// srvHomeUnclosed와 완전히 동일한 close 조건 + 날짜 펼치기 로직 사용.
// 차이점: 날짜를 카운팅하는 대신 per-date (totalConfirmed, closedCount) 를 반환.
//
// close condition (srvHomeUnclosed L24996과 동일):
//   wageStatus === "confirmed" || wageStatus === "transferred" || status === "NO_SHOW"
//
// open-ended 장기(endTs 없음) → yesterdayMidnight까지 확장 (srvHomeUnclosed 동일 semantics).
// [PHASE-2B.1] 기존 skip → 확장으로 변경. getUnclosedDaysCount Flutter canonical과 parity 확보.
// safety cap 3650일 → throw → caller available:false 처리.

interface UnclosedQueueRow {
  businessId:     string;
  businessName:   string;
  workDateStr:    string; // 'YYYY-MM-DD'
  totalConfirmed: number;
  closedCount:    number;
  remainingCount: number;
}

async function srvUnclosedQueueForBiz(
  bizId:            string,
  todayKSTMidnight: Date,
  todayMs:          number,
  bizName:          string,
): Promise<UnclosedQueueRow[]> {
  const KST_MS = 9 * 60 * 60 * 1000;
  const DAY_MS = 24 * 60 * 60 * 1000;
  const yesterdayMidnight = new Date(todayMs - DAY_MS);
  const KR_DAYS = ["일", "월", "화", "수", "목", "금", "토"];

  // 활성 지원서 조회 — srvHomeUnclosed와 동일 쿼리
  const appSnap = await db.collection("applications")
    .where("businessId", "==", bizId)
    .where("status", "in", ["CONFIRMED", "CONTRACT_PENDING"])
    .select("type", "workDate", "workEndDate", "desiredStartDate",
            "actualResignDate", "workDays", "leaveDates", "extraWorkDates")
    .get();
  if (appSnap.empty) return [];

  // dateToAppIds: dateStr(YYYYMMDD) → Set<appId>
  const dateToAppIds = new Map<string, Set<string>>();

  for (const appDoc of appSnap.docs) {
    const d = appDoc.data();
    const appId = appDoc.id;
    const isLong = d["type"] === "long_term";

    if (!isLong) {
      // 단기 — srvHomeUnclosed L24922~24929와 동일
      const wdTs = d["workDate"] as admin.firestore.Timestamp | undefined;
      if (!wdTs || wdTs.toMillis() >= todayMs) continue;
      const kst = new Date(wdTs.toMillis() + KST_MS);
      const midnight = new Date(
        Date.UTC(kst.getUTCFullYear(), kst.getUTCMonth(), kst.getUTCDate()) - KST_MS
      );
      const dateStr = srvHomeDateStr(midnight);
      if (!dateToAppIds.has(dateStr)) dateToAppIds.set(dateStr, new Set());
      dateToAppIds.get(dateStr)!.add(appId);

    } else {
      // 장기 날짜 펼치기 — srvHomeUnclosed와 동일 로직 (PHASE-2B.1 open-ended 수정 포함)
      const startTs = (d["desiredStartDate"] ?? d["workDate"]) as admin.firestore.Timestamp | undefined;
      const endTs   = (d["actualResignDate"] ?? d["workEndDate"]) as admin.firestore.Timestamp | undefined;
      // [PHASE-2B.1] open-ended(endTs==null) → yesterdayMidnight까지 확장
      if (!startTs) continue;

      const startKST = new Date(startTs.toMillis() + KST_MS);
      let current = new Date(
        Date.UTC(startKST.getUTCFullYear(), startKST.getUTCMonth(), startKST.getUTCDate()) - KST_MS
      );
      const actualEndMs = endTs
        ? Math.min(endTs.toMillis(), yesterdayMidnight.getTime())
        : yesterdayMidnight.getTime(); // open-ended: 어제까지
      if (current.getTime() > actualEndMs) continue;

      const workDays   = (d["workDays"]       as string[] | undefined) ?? [];
      const leaveDates = (d["leaveDates"]     as admin.firestore.Timestamp[] | undefined) ?? [];
      const extraDates = (d["extraWorkDates"] as admin.firestore.Timestamp[] | undefined) ?? [];

      const CAP_DAYS = 3650;
      let safety = 0;
      while (current.getTime() <= actualEndMs) {
        if (safety >= CAP_DAYS) {
          throw new Error(
            `[unclosedQueue] ${bizId}/${appId} 날짜 범위 ${CAP_DAYS}일 초과 — available:false`
          );
        }
        safety++;
        const nextDay = new Date(current.getTime() + DAY_MS);
        const weekday = KR_DAYS[new Date(current.getTime() + KST_MS).getUTCDay()];
        const curMs   = current.getTime();
        const nextMs  = nextDay.getTime();

        const isWorkDay = workDays.includes(weekday);
        const isExtra   = extraDates.some((ts) => {
          const m = ts.toMillis(); return m >= curMs && m < nextMs;
        });
        const isLeave   = leaveDates.some((ts) => {
          const m = ts.toMillis(); return m >= curMs && m < nextMs;
        });

        if (!isLeave && (isWorkDay || isExtra)) {
          const dateStr = srvHomeDateStr(current);
          if (!dateToAppIds.has(dateStr)) dateToAppIds.set(dateStr, new Set());
          dateToAppIds.get(dateStr)!.add(appId);
        }
        current = nextDay;
      }
    }
  }

  if (dateToAppIds.size === 0) return [];

  // attendance 배치 읽기 (400개씩) — srvHomeUnclosed L24988~25000과 동일
  const allDocIds: string[] = [];
  for (const [dateStr, appIds] of dateToAppIds) {
    for (const appId of appIds) allDocIds.push(`${appId}_${dateStr}`);
  }

  const closedSet = new Set<string>();
  const BATCH = 400;
  for (let i = 0; i < allDocIds.length; i += BATCH) {
    const refs = allDocIds.slice(i, i + BATCH).map((id) => db.collection("attendance").doc(id));
    const snaps = await db.getAll(...refs);
    for (const snap of snaps) {
      if (!snap.exists) continue;
      const sd = snap.data()!;
      const ws = (sd["wageStatus"] as string) ?? "";
      const st = (sd["status"]    as string) ?? "";
      // srvHomeUnclosed L24996과 동일 close 조건
      if (ws === "confirmed" || ws === "transferred" || st === "NO_SHOW") {
        closedSet.add(snap.id);
      }
    }
  }

  // per-date row 생성 (remainingCount > 0인 항목만)
  const rows: UnclosedQueueRow[] = [];
  for (const [dateStr, appIds] of dateToAppIds) {
    let closedCount = 0;
    for (const appId of appIds) {
      if (closedSet.has(`${appId}_${dateStr}`)) closedCount++;
    }
    const totalConfirmed = appIds.size;
    const remainingCount = totalConfirmed - closedCount;
    if (remainingCount > 0) {
      // dateStr "YYYYMMDD" → "YYYY-MM-DD"
      const workDateStr = `${dateStr.slice(0,4)}-${dateStr.slice(4,6)}-${dateStr.slice(6,8)}`;
      rows.push({businessId: bizId, businessName: bizName, workDateStr, totalConfirmed, closedCount, remainingCount});
    }
  }
  return rows;
}

// ─── Section 헬퍼: Wage Change Request ───────────────────────────────────────

async function srvHomeWageChangeRequest(bizId: string): Promise<{count: number}> {
  // count() aggregation — 건수 무관 exact count, document fetch 없음
  // 조건: businessId==x AND status==PENDING (join/client-filter 없음)
  // firebase-admin v12 이상에서 지원
  const agg = await db.collection("payment_change_requests")
    .where("businessId", "==", bizId)
    .where("status", "==", "PENDING")
    .count()
    .get();
  return {count: agg.data().count};
}

// ─── Section 헬퍼: Settlement Request ────────────────────────────────────────

async function srvHomeSettlementRequest(bizId: string): Promise<{count: number}> {
  // count() aggregation — 건수 무관 exact count, document fetch 없음
  // 조건: businessId==x AND status==PENDING (join/client-filter 없음)
  // firebase-admin v12 이상에서 지원
  const agg = await db.collection("interim_settlement_requests")
    .where("businessId", "==", bizId)
    .where("status", "==", "PENDING")
    .count()
    .get();
  return {count: agg.data().count};
}

// ─── Section 헬퍼: Schedule Change Request (스케줄 변경 요청) ────────────────

/**
 * 관리자가 응답해야 하는 스케줄 변경 요청 건수.
 *
 * [AH-V2-02C] 방향이 중요하다. requestedBy == "APPLICANT" 인 요청
 * (LEAVE / CANCEL_LEAVE / CANCEL_EXTRA)만 관리자의 처리 대상이다.
 * requestedBy == "ADMIN" (NO_WORK / EXTRA_WORK)은 관리자가 보낸 요청의
 * 근로자 응답을 기다리는 상태이므로 "처리할 일"이 아니다.
 *
 * 방향 필터를 쿼리에 포함한다 — PENDING 전체를 받아 메모리에서 거르면
 * 사업장당 문서 fetch가 발생한다.
 *
 * @param {string} bizId 대상 사업장
 * @return {Promise<{count: number}>} 관리자 응답 대기 건수
 */
async function srvHomeScheduleChangeRequest(
  bizId: string
): Promise<{count: number}> {
  const agg = await db.collection("schedule_change_requests")
    .where("businessId", "==", bizId)
    .where("status", "==", "PENDING")
    .where("requestedBy", "==", "APPLICANT")
    .count()
    .get();
  return {count: agg.data().count};
}

// ─── Section 헬퍼: Resign Request (퇴사 요청) ────────────────────────────────

/**
 * 퇴사 요청 대기 건수 + 자동 승인 임박 건수.
 *
 * [AH-V2-02B] 다른 Home task와 달리 방치하면 시스템이 대신 결정한다.
 * D+3 자동 승인(processContractRenewalChecks)이 쓰는 것과 동일한 기준을
 * 그대로 쓴다 — resignRequestedAt, KST 자정, 달력 3일.
 * 두 기준이 어긋나면 Home이 "아직 여유 있음"으로 보이는데 실제로는
 * 오늘 밤 자동 승인되는 일이 생긴다.
 *
 * soonCount = 다음 자정 스케줄러에서 자동 승인될 건
 *   = resignRequestedAt <= (오늘 KST 자정 − 2일)
 *   (스케줄러는 −3일 경계를 쓰므로, 내일 자정에는 −2일 이전 건이 대상이 된다)
 *
 * @param {string} bizId 대상 사업장
 * @param {Date} todayKSTMidnight 오늘 KST 자정의 UTC instant.
 *   srvHomeKSTMidnight()가 반환하는 값이며, 스케줄러의
 *   `todayKST.setHours(0,0,0,0) - KST_OFFSET_MS`와 동일한 시점이다.
 * @return {Promise<{count: number, soonCount: number}>} 대기 건수와 임박 건수
 */
async function srvHomeResignRequest(
  bizId: string,
  todayKSTMidnight: Date
): Promise<{count: number; soonCount: number}> {
  const base = db.collection("applications")
    .where("businessId", "==", bizId)
    .where("resignStatus", "==", "PENDING");

  // 스케줄러 경계(−3일)보다 하루 앞선 −2일 → "다음 자정에 자동 승인될 건"
  // todayKSTMidnight는 이미 UTC instant이므로 offset을 다시 빼지 않는다.
  const soonBoundary = admin.firestore.Timestamp.fromDate(
    new Date(todayKSTMidnight.getTime() - 2 * 24 * 60 * 60 * 1000)
  );

  // count() aggregation — 문서 fetch 없음
  const [allAgg, soonAgg] = await Promise.all([
    base.count().get(),
    base.where("resignRequestedAt", "<=", soonBoundary).count().get(),
  ]);
  return {count: allAgg.data().count, soonCount: soonAgg.data().count};
}

// ─── Section 헬퍼: Expiring Contract (D+15) ──────────────────────────────────

async function srvHomeExpiringContract(
  bizId: string,
  todayMs: number
): Promise<{count: number}> {
  const todayTs    = Timestamp.fromMillis(todayMs);
  const in16DaysTs = Timestamp.fromMillis(todayMs + 16 * 24 * 60 * 60 * 1000);

  // limit 제거: workEndDate 범위 [today, today+16)이 자연 상한이므로
  // 임의 limit으로 인한 silent undercount 불필요
  // 기존 composite index: (businessId ASC, status ASC, workEndDate ASC) 사용
  const snap = await db.collection("applications")
    .where("businessId", "==", bizId)
    .where("status", "==", "CONFIRMED")
    .where("workEndDate", ">=", todayTs)
    .where("workEndDate", "<",  in16DaysTs)
    // [6.1 HOME-EXPIRING-01] resignStatus 추가 — 퇴사 승인/자동승인 건 제외용
    .select("type", "workEndDate", "actualResignDate", "terminationStatus", "resignStatus")
    .get();

  let count = 0;
  for (const doc of snap.docs) {
    const d = doc.data();
    if (d["type"] !== "long_term") continue;
    // [6.1 HOME-EXPIRING-01] ExpiringContractsScreen.isTerminationApproved와 동일 exclusion semantics:
    //   terminationStatus: APPROVED | AUTO_APPROVED
    //   resignStatus:      APPROVED | AUTO_APPROVED
    // 이전에는 terminationStatus=APPROVED만 체크 → resignStatus 및 AUTO_APPROVED 누락 → 홈 카운트 과다
    if (d["terminationStatus"] === "APPROVED" || d["terminationStatus"] === "AUTO_APPROVED") continue;
    if (d["resignStatus"]       === "APPROVED" || d["resignStatus"]       === "AUTO_APPROVED") continue;
    const endTs = (d["actualResignDate"] ?? d["workEndDate"]) as admin.firestore.Timestamp | undefined;
    if (!endTs) continue;
    const diffDays = Math.floor((endTs.toMillis() - todayMs) / (24 * 60 * 60 * 1000));
    if (diffDays >= 0 && diffDays <= 15) count++;
  }
  return {count};
}

// ─── Main CF ─────────────────────────────────────────────────────────────────

/**
 * Admin Home Summary 단일 CF — 클라이언트 N×CF 호출 → 1회 호출로 대체
 *
 * BEFORE: N Firestore reads + ~10N CF calls (action summary only, N=businesses)
 * AFTER:  1 CF call (내부는 Admin SDK direct reads, HTTP overhead 없음)
 *
 * scope:     서버 결정 (client-supplied businessIds 신뢰 금지)
 * SubAdmin:  canManageWage / canManageContract / canManageTo gate 적용
 * "거짓 0": 쿼리 실패 시 available:false 반환 — 0과 "데이터 없음" 구분
 */
export const callableGetAdminHomeSummary = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    if (!request.auth) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");
    const uid = request.auth.uid;

    // 1. 사용자 문서 — role + businessIds 서버 결정
    const userSnap = await db.collection("users").doc(uid).get();
    if (!userSnap.exists) throw new HttpsError("not-found", "사용자를 찾을 수 없습니다.");
    const userData = userSnap.data()!;
    const role = (userData["role"] as string) ?? "";

    let businessIds: string[];
    let isSubAdmin = false;

    if (role === "BUSINESS_ADMIN" || role === "SUPER_ADMIN") {
      businessIds = (userData["managedBusinessIds"] as string[] | undefined) ?? [];
    } else if (role === "USER") {
      // [HOTFIX 1D-R1] ALfit SUB_ADMIN = role "USER" + non-empty subAdminBusinessIds
      // "SUB_ADMIN" role string은 ALfit Firestore에 존재하지 않음 (dead code였음)
      const subAdminIds = (userData["subAdminBusinessIds"] as string[] | undefined) ?? [];
      if (subAdminIds.length === 0) {
        // 일반 USER (subAdminBusinessIds 없음) → 접근 거부
        throw new HttpsError("permission-denied", "관리자만 접근 가능합니다.");
      }
      // 유효한 SUB_ADMIN: subAdminBusinessIds로 scope 결정
      isSubAdmin = true;
      businessIds = subAdminIds;
    } else {
      throw new HttpsError("permission-denied", "관리자만 접근 가능합니다.");
    }

    // [PH1D] SUB_ADMIN selectedBusinessId scope 지원
    // client-supplied 값을 그대로 신뢰하지 않고 서버가 membership 검증 후 scope 결정
    // OWNER: scope argument 무시 (기존 aggregate 유지 — OWNER 단일 scope 불필요)
    if (isSubAdmin) {
      const {selectedBusinessId} = (request.data ?? {}) as {selectedBusinessId?: string};
      if (
        typeof selectedBusinessId === "string" &&
        selectedBusinessId.trim().length > 0
      ) {
        const trimmedId = selectedBusinessId.trim();
        if (!businessIds.includes(trimmedId)) {
          // 실제 subAdminBusinessIds에 없는 사업장 → 접근 거부
          throw new HttpsError("permission-denied", "해당 사업장에 대한 접근 권한이 없습니다.");
        }
        // 검증 통과 — 선택 사업장만 scope로 좁힘
        businessIds = [trimmedId];
      }
    }

    // 빈 scope → 전부 0 즉시 반환
    //
    // [FP-02] available 은 "쿼리가 성공했는가"다(거짓 0 방지용).
    //   관리 중인 사업장이 0개인 것은 **쿼리 실패가 아니라 정상 상태**다 —
    //   조회할 scope가 없을 뿐이고, 처리할 일도 실제로 0건이다.
    //   이전에는 available:false 로 반환해 클라이언트가 다섯 줄 모두
    //   '조회 실패'로 렌더했고, 갓 가입한 관리자의 첫 홈이 고장난 것처럼 보였다.
    //   available:true + count:0 으로 두면 클라이언트의 기존 규칙
    //   (available && count == 0 → 행 숨김)이 그대로 처리한다.
    //   실제 쿼리 실패는 아래 aggSimple 경로에서 계속 available:false 로 남는다.
    if (businessIds.length === 0) {
      const emptySimple = {available: true, count: 0, byBusiness: [] as unknown[]};
      return {
        scope: {businessCount: 0},
        actions: {
          approval:          {...emptySimple, overdueCount: 0},
          unsentContract:    emptySimple,
          unpaidWage:        {...emptySimple, overdueCount: 0, missingDueDateCount: 0},
          unclosed:          {...emptySimple, oldestDate: null as string | null},
          wageChangeRequest: emptySimple,
          settlementRequest: emptySimple,
          resignRequest:     {...emptySimple, soonCount: 0},
          scheduleChangeRequest: emptySimple,
        },
        upcoming: {expiringContract: emptySimple},
        generatedAt: Date.now(),
      };
    }

    // 2. SubAdmin 권한 맵 조회 (members/{uid}.permissions)
    const permMap: Record<string, Record<string, boolean>> = {};
    if (isSubAdmin) {
      const memberSnaps = await Promise.all(
        businessIds.map((bizId) =>
          db.collection("businesses").doc(bizId).collection("members").doc(uid).get()
        )
      );
      memberSnaps.forEach((snap, i) => {
        permMap[businessIds[i]] =
          ((snap.data() ?? {})["permissions"] ?? {}) as Record<string, boolean>;
      });
    }

    // 3. KST 오늘 자정
    const todayKSTMidnight = srvHomeKSTMidnight();
    const todayMs = todayKSTMidnight.getTime();

    // 4. 사업장별 병렬 조회
    interface BizResult {
      bizId: string;
      approval?:          {total: number; overdue: number};
      unsentContract?:    {count: number};
      unpaidWage?:        {count: number; overdue: number; missingDueDate: number};
      unclosed?:          {count: number; oldestDate: string | null};
      wageChangeRequest?: {count: number};
      settlementRequest?: {count: number};
      resignRequest?:     {count: number; soonCount: number};
      scheduleChange?:    {count: number};
      expiringContract?:  {count: number};
    }

    const bizResults: BizResult[] = await Promise.all(
      businessIds.map(async (bizId): Promise<BizResult> => {
        const perms    = permMap[bizId] ?? {};
        const canTo    = !isSubAdmin || perms["canManageTo"]       === true;
        const canWage  = !isSubAdmin || perms["canManageWage"]     === true;
        const canContr = !isSubAdmin || perms["canManageContract"] === true;

        // [AH-V2-02B] 퇴사 요청은 canManageWorkers — 승인 callable과 동일 권한
        const canWork  = !isSubAdmin || perms["canManageWorkers"] === true;

        const [appR, unsentR, unpaidR, unclosedR, wageChgR, settlR, resignR,
          schedR, expiringR] =
          await Promise.allSettled([
            canTo    ? srvHomeApproval(bizId, todayMs)            : Promise.resolve<undefined>(undefined),
            canContr ? srvHomeUnsentContract(bizId)               : Promise.resolve<undefined>(undefined),
            canWage  ? srvHomeUnpaidWage(bizId, todayMs)          : Promise.resolve<undefined>(undefined),
            canWage  ? srvHomeUnclosed(bizId, todayKSTMidnight)   : Promise.resolve<undefined>(undefined),
            canWage  ? srvHomeWageChangeRequest(bizId)            : Promise.resolve<undefined>(undefined),
            canWage  ? srvHomeSettlementRequest(bizId)            : Promise.resolve<undefined>(undefined),
            canWork  ? srvHomeResignRequest(bizId, todayKSTMidnight) : Promise.resolve<undefined>(undefined),
            canWork  ? srvHomeScheduleChangeRequest(bizId)        : Promise.resolve<undefined>(undefined),
            canContr ? srvHomeExpiringContract(bizId, todayMs)    : Promise.resolve<undefined>(undefined),
          ]);

        if (appR.status      === "rejected") console.error(`[adminHome] ${bizId} approval 실패:`, appR.reason);
        if (unsentR.status   === "rejected") console.error(`[adminHome] ${bizId} unsentContract 실패:`, unsentR.reason);
        if (unpaidR.status   === "rejected") console.error(`[adminHome] ${bizId} unpaidWage 실패:`, unpaidR.reason);
        if (unclosedR.status === "rejected") console.error(`[adminHome] ${bizId} unclosed 실패:`, unclosedR.reason);
        if (wageChgR.status  === "rejected") console.error(`[adminHome] ${bizId} wageChangeRequest 실패:`, wageChgR.reason);
        if (settlR.status    === "rejected") console.error(`[adminHome] ${bizId} settlementRequest 실패:`, settlR.reason);
        if (resignR.status   === "rejected") console.error(`[adminHome] ${bizId} resignRequest 실패:`, resignR.reason);
        if (schedR.status    === "rejected") console.error(`[adminHome] ${bizId} scheduleChange 실패:`, schedR.reason);
        if (expiringR.status === "rejected") console.error(`[adminHome] ${bizId} expiringContract 실패:`, expiringR.reason);

        return {
          bizId,
          approval:          appR.status      === "fulfilled" ? appR.value      : undefined,
          unsentContract:    unsentR.status   === "fulfilled" ? unsentR.value   : undefined,
          unpaidWage:        unpaidR.status   === "fulfilled" ? unpaidR.value   : undefined,
          unclosed:          unclosedR.status === "fulfilled" ? unclosedR.value : undefined,
          wageChangeRequest: wageChgR.status  === "fulfilled" ? wageChgR.value  : undefined,
          settlementRequest: settlR.status    === "fulfilled" ? settlR.value    : undefined,
          resignRequest:     resignR.status   === "fulfilled" ? resignR.value   : undefined,
          scheduleChange:    schedR.status    === "fulfilled" ? schedR.value    : undefined,
          expiringContract:  expiringR.status === "fulfilled" ? expiringR.value : undefined,
        };
      })
    );

    // 5. 집계 헬퍼
    // available: 권한 있는 사업장 중 하나라도 쿼리 실패(undefined)면 false
    // 권한 없는 사업장에서 undefined인 건 정상 (available 계산 제외)
    const getPerms = (bizId: string) => permMap[bizId] ?? {};
    const hasBizPerm = (bizId: string, key: string) =>
      !isSubAdmin || getPerms(bizId)[key] === true;

    type SimpleSection = {available: boolean; count: number; byBusiness: Array<{businessId: string; count: number}>};
    const aggSimple = (
      permKey: string,
      getCount: (r: BizResult) => number | undefined
    ): SimpleSection => {
      let permCount = 0, successCount = 0, total = 0;
      const byBusiness: Array<{businessId: string; count: number}> = [];
      for (const r of bizResults) {
        if (!hasBizPerm(r.bizId, permKey)) continue;
        permCount++;
        const v = getCount(r);
        if (v !== undefined) {
          successCount++;
          total += v;
          if (v > 0) byBusiness.push({businessId: r.bizId, count: v});
        }
      }
      return {
        available: permCount > 0 && successCount === permCount,
        count: total,
        byBusiness,
      };
    };

    // approval (overdueCount 포함)
    const approvalByBiz: Array<{businessId: string; count: number; overdueCount: number}> = [];
    let approvalTotal = 0, approvalOverdue = 0;
    let appPermCount = 0, appSuccessCount = 0;
    for (const r of bizResults) {
      if (!hasBizPerm(r.bizId, "canManageTo")) continue;
      appPermCount++;
      if (!r.approval) continue;
      appSuccessCount++;
      approvalTotal  += r.approval.total;
      approvalOverdue += r.approval.overdue;
      if (r.approval.total > 0) {
        approvalByBiz.push({businessId: r.bizId, count: r.approval.total, overdueCount: r.approval.overdue});
      }
    }

    // unpaidWage (overdueCount + missingDueDateCount 포함)
    const unpaidByBiz: Array<{businessId: string; count: number; overdueCount: number; missingDueDateCount: number}> = [];
    let unpaidTotal = 0, unpaidOverdue = 0, unpaidMissing = 0;
    let unpaidPermCount = 0, unpaidSuccessCount = 0;
    for (const r of bizResults) {
      if (!hasBizPerm(r.bizId, "canManageWage")) continue;
      unpaidPermCount++;
      if (!r.unpaidWage) continue;
      unpaidSuccessCount++;
      unpaidTotal   += r.unpaidWage.count;
      unpaidOverdue += r.unpaidWage.overdue;
      unpaidMissing += r.unpaidWage.missingDueDate;
      if (r.unpaidWage.count > 0 || r.unpaidWage.missingDueDate > 0) {
        unpaidByBiz.push({
          businessId:          r.bizId,
          count:               r.unpaidWage.count,
          overdueCount:        r.unpaidWage.overdue,
          missingDueDateCount: r.unpaidWage.missingDueDate,
        });
      }
    }

    // unclosed (oldestDate 포함)
    const unclosedByBiz: Array<{businessId: string; count: number; oldestDate: string | null}> = [];
    let unclosedTotal = 0, unclosedOldest: string | null = null;
    let unclosedPermCount = 0, unclosedSuccessCount = 0;
    for (const r of bizResults) {
      if (!hasBizPerm(r.bizId, "canManageWage")) continue;
      unclosedPermCount++;
      if (!r.unclosed) continue;
      unclosedSuccessCount++;
      unclosedTotal += r.unclosed.count;
      if (r.unclosed.count > 0) {
        unclosedByBiz.push({businessId: r.bizId, count: r.unclosed.count, oldestDate: r.unclosed.oldestDate});
        if (r.unclosed.oldestDate) {
          if (!unclosedOldest || r.unclosed.oldestDate < unclosedOldest) {
            unclosedOldest = r.unclosed.oldestDate;
          }
        }
      }
    }

    // [AH-V2-02B] 자동 승인 임박 건수 합산.
    // 실패 사업장은 값이 없어 빠지며, 그 사실은 available:false가 전달한다.
    let resignSoonTotal = 0;
    for (const r of bizResults) {
      if (!hasBizPerm(r.bizId, "canManageWorkers")) continue;
      resignSoonTotal += r.resignRequest?.soonCount ?? 0;
    }

    // 최종 결과 조립
    return {
      scope: {businessCount: businessIds.length},
      actions: {
        approval: {
          available:    appPermCount > 0 && appSuccessCount === appPermCount,
          count:        approvalTotal,
          overdueCount: approvalOverdue,
          byBusiness:   approvalByBiz,
        },
        unsentContract:    aggSimple("canManageContract", (r) => r.unsentContract?.count),
        unpaidWage: {
          available:           unpaidPermCount > 0 && unpaidSuccessCount === unpaidPermCount,
          count:               unpaidTotal,
          overdueCount:        unpaidOverdue,
          missingDueDateCount: unpaidMissing,
          byBusiness:          unpaidByBiz,
        },
        unclosed: {
          available:  unclosedPermCount > 0 && unclosedSuccessCount === unclosedPermCount,
          count:      unclosedTotal,
          oldestDate: unclosedOldest,
          byBusiness: unclosedByBiz,
        },
        wageChangeRequest: aggSimple("canManageWage",    (r) => r.wageChangeRequest?.count),
        settlementRequest: aggSimple("canManageWage",    (r) => r.settlementRequest?.count),
        resignRequest: {...aggSimple("canManageWorkers",
          (r) => r.resignRequest?.count), soonCount: resignSoonTotal},
        scheduleChangeRequest: aggSimple("canManageWorkers",
          (r) => r.scheduleChange?.count),
      },
      upcoming: {
        expiringContract: aggSimple("canManageContract", (r) => r.expiringContract?.count),
      },
      generatedAt: Date.now(),
    };
  }
);

// ─── Admin 마감 필요 Action Queue ────────────────────────────────────────────
/**
 * UnclosedActionQueueScreen용 — business×workDate 미마감 항목 목록 반환
 *
 * canonical unit: business × workDate (1건 = 한 사업장의 한 근무일)
 * close condition: srvUnclosedQueueForBiz (= srvHomeUnclosed L24996 동일)
 * scope: 서버 결정 (client-supplied IDs 신뢰 금지)
 * SubAdmin: canManageWage 권한 사업장만 포함
 * sort: workDate ASC (oldest first) — 정렬은 서버가 수행
 * cap: ROW_CAP(500) 초과 시 available:false (silent truncation 금지)
 *
 * KNOWN LIMITATION:
 *   open-ended 장기 근로자(endDate 없음)는 srvHomeUnclosed와 동일하게 skip.
 *   Home이 LEGACY _loadUnclosedDaysCount()를 사용하는 동안, 해당 케이스에서
 *   Home count(포함) vs Queue count(미포함)가 미미하게 다를 수 있음.
 *   PHASE 3에서 Home → AdminHomeSummaryService 전환 시 해소 예정.
 */
export const callableGetUnclosedActionQueue = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    if (!request.auth) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");
    const uid = request.auth.uid;

    // 1. 사용자 문서 — role + businessIds 서버 결정 (callableGetAdminHomeSummary와 동일 패턴)
    const userSnap = await db.collection("users").doc(uid).get();
    if (!userSnap.exists) throw new HttpsError("not-found", "사용자를 찾을 수 없습니다.");
    const userData = userSnap.data()!;
    const role = (userData["role"] as string) ?? "";

    let businessIds: string[];
    let isSubAdmin = false;

    if (role === "BUSINESS_ADMIN" || role === "SUPER_ADMIN") {
      businessIds = (userData["managedBusinessIds"] as string[] | undefined) ?? [];
    } else if (role === "USER") {
      // [AUTHZ.2] ALfit SUB_ADMIN = role "USER" + non-empty subAdminBusinessIds
      // 기존: role === "SUB_ADMIN" → dead branch (해당 role string이 Firestore에 존재하지 않음)
      // callableGetAdminHomeSummary 수정(HOTFIX 1D-R1)과 동일한 패턴 적용
      const subBizIds: string[] =
        (userData["subAdminBusinessIds"] as string[] | undefined) ??
        (userData["subAdminOf"] ? [(userData["subAdminOf"] as string)] : []);
      if (subBizIds.length === 0) {
        throw new HttpsError("permission-denied", "관리자만 접근 가능합니다.");
      }
      isSubAdmin = true;
      businessIds = subBizIds;
    } else {
      throw new HttpsError("permission-denied", "관리자만 접근 가능합니다.");
    }

    if (businessIds.length === 0) {
      return {available: true, rows: [] as UnclosedQueueRow[], hasMore: false};
    }

    // 2. SubAdmin 권한 맵 조회 — canManageWage 필요 (callableGetAdminHomeSummary와 동일 패턴)
    const permMap: Record<string, Record<string, boolean>> = {};
    if (isSubAdmin) {
      const memberSnaps = await Promise.all(
        businessIds.map((bizId) =>
          db.collection("businesses").doc(bizId).collection("members").doc(uid).get()
        )
      );
      memberSnaps.forEach((snap, i) => {
        permMap[businessIds[i]] =
          ((snap.data() ?? {})["permissions"] ?? {}) as Record<string, boolean>;
      });
    }

    // 권한 있는 사업장만 필터 (canManageWage)
    const permittedBizIds = businessIds.filter((bizId) =>
      !isSubAdmin || (permMap[bizId]?.["canManageWage"] === true)
    );

    if (permittedBizIds.length === 0) {
      return {available: true, rows: [] as UnclosedQueueRow[], hasMore: false};
    }

    // 3. 사업장명 일괄 조회 (display용)
    const bizSnaps = await Promise.all(
      permittedBizIds.map((id) => db.collection("businesses").doc(id).get())
    );
    const bizNames: Record<string, string> = {};
    bizSnaps.forEach((snap) => {
      bizNames[snap.id] = (snap.data()?.["name"] as string) ?? snap.id;
    });

    // 4. KST 오늘 자정
    const todayKSTMidnight = srvHomeKSTMidnight();
    const todayMs = todayKSTMidnight.getTime();

    // 5. 사업장별 병렬 조회
    const ROW_CAP = 500;
    const allRows: UnclosedQueueRow[] = [];
    let anyFailed = false;

    const bizResultsSettled = await Promise.allSettled(
      permittedBizIds.map((bizId) =>
        srvUnclosedQueueForBiz(bizId, todayKSTMidnight, todayMs, bizNames[bizId])
      )
    );

    for (const result of bizResultsSettled) {
      if (result.status === "rejected") {
        console.error("[unclosedQueue] 사업장 조회 실패:", result.reason);
        anyFailed = true;
      } else {
        allRows.push(...result.value);
      }
    }

    // cap 초과 또는 쿼리 실패 → available:false (거짓 0 / 거짓 count 금지)
    if (anyFailed || allRows.length > ROW_CAP) {
      return {
        available:  false,
        rows:       [] as UnclosedQueueRow[],
        hasMore:    false,
        error:      allRows.length > ROW_CAP ? "ROW_CAP_EXCEEDED" : "QUERY_FAILED",
      };
    }

    // 6. oldest first 정렬 (workDateStr YYYY-MM-DD 사전순 = 날짜순)
    allRows.sort((a, b) => a.workDateStr.localeCompare(b.workDateStr));

    return {available: true, rows: allRows, hasMore: false};
  }
);

// ─── callableGetHistoricalContracts ──────────────────────────────────────────
// [DATA-ARCH-CONTRACT-P3] 전(前) 사업장 오너 — 보존된 계약서 목록 조회
// 호출 가능 조건: request.auth.uid == historicalOwnerUid (자기 자신만)
// 반환: 요약 목록 (pdfUrl 미포함, pdfAvailable boolean만 포함)
// Input:  { lastDocId?: string, pageSize?: number }
// Output: { contracts: [...], lastDocId: string | null, hasMore: boolean }
export const callableGetHistoricalContracts = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    // ── 1. 인증 ────────────────────────────────────────────────────────────────
    if (!request.auth) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");
    const callerUid = request.auth.uid;

    // ── 2. 입력 검증 ───────────────────────────────────────────────────────────
    // [GAP-A] strict pageSize: coerce/clamp 금지 — 비정수·범위외·NaN·Infinity 즉시 거부
    const rawData = (request.data ?? {}) as Record<string, unknown>;
    // [GAP-C] strict lastDocId: 타입 오류/빈 문자열 즉시 거부 (C-I2 + C-I3 해소)
    const rawLastDocId = rawData.lastDocId;
    let lastDocId: string | undefined;
    if (rawLastDocId === undefined || rawLastDocId === null) {
      lastDocId = undefined;
    } else if (
      typeof rawLastDocId !== "string" ||
      rawLastDocId.trim().length === 0
    ) {
      throw new HttpsError("invalid-argument", "유효하지 않은 커서입니다.");
    } else {
      lastDocId = rawLastDocId;
    }
    const rawPageSize = rawData.pageSize;
    let pageSize: number;
    if (rawPageSize === undefined || rawPageSize === null) {
      pageSize = 20;
    } else if (
      typeof rawPageSize !== "number" ||
      !Number.isFinite(rawPageSize) ||
      !Number.isInteger(rawPageSize) ||
      rawPageSize < 1 ||
      rawPageSize > 100
    ) {
      throw new HttpsError("invalid-argument", "pageSize는 1 이상 100 이하의 정수여야 합니다.");
    } else {
      pageSize = rawPageSize;
    }

    // ── 3. 기본 쿼리 (status 필터 없음 — 모든 보존 기록 노출) ─────────────────
    let q: FirebaseFirestore.Query = db
      .collection("employment_contracts")
      .where("historicalOwnerUid", "==", callerUid)
      .orderBy("createdAt", "desc")
      .limit(pageSize + 1);

    // ── 4. 커서 (다른 소유자 문서 커서 우회 차단) ──────────────────────────────
    if (lastDocId) {
      const lastSnap = await db.collection("employment_contracts").doc(lastDocId).get();
      if (!lastSnap.exists) {
        throw new HttpsError("invalid-argument", "유효하지 않은 커서입니다.");
      }
      if (lastSnap.data()?.historicalOwnerUid !== callerUid) {
        throw new HttpsError("permission-denied", "접근 권한이 없는 커서입니다.");
      }
      // [GAP-B] createdAt Timestamp 검증 — orderBy 기준 필드 누락 시 커서 거부
      const cursorCreatedAt = lastSnap.data()?.createdAt;
      if (!(cursorCreatedAt instanceof Timestamp)) {
        throw new HttpsError("invalid-argument", "유효하지 않은 커서입니다.");
      }
      q = q.startAfter(lastSnap);
    }

    // ── 5. 쿼리 실행 ───────────────────────────────────────────────────────────
    const snap = await q.get();
    const hasMore = snap.docs.length > pageSize;
    const docs = hasMore ? snap.docs.slice(0, pageSize) : snap.docs;

    // ── 6. 요약 매핑 ───────────────────────────────────────────────────────────
    // snapshot에서 동결된 사업장명·근무자명 사용 — 삭제된 business/user 생존
    // 내부 필드(historicalOwnerUid, pdfUrl, 서명URL, 해시, ID참조 등) 미포함
    const contracts = docs.map((d) => {
      const data = d.data();
      const snapshotData = (
        typeof data.snapshot === "object" && data.snapshot !== null
          ? data.snapshot
          : {}
      ) as Record<string, unknown>;

      const summary: Record<string, unknown> = {
        contractId:      d.id,
        businessId:      data.businessId      ?? null,
        businessName:    snapshotData.businessName ?? null,
        workerId:        data.workerId         ?? null,
        workerName:      snapshotData.workerName   ?? null,
        status:          data.status           ?? null,
        isLongTerm:      data.isLongTerm       ?? null,
        createdAt:       data.createdAt        ?? null,
        employerSignedAt: data.employerSignedAt ?? null,
        workerSignedAt:  data.workerSignedAt   ?? null,
        contractVoidedAt: data.contractVoidedAt ?? null,
        voidReason:      data.voidReason       ?? null,
        // pdfUrl 직접 노출 금지 — boolean만 반환
        pdfAvailable:
          typeof data.pdfUrl === "string" &&
          (data.pdfUrl as string).trim().length > 0,
      };
      return serializeFirestoreData(summary);
    });

    return {
      contracts,
      lastDocId: docs.length > 0 ? docs[docs.length - 1].id : null,
      hasMore,
    };
  }
);

// ─── callableGetHistoricalContractById ───────────────────────────────────────
// [DATA-ARCH-CONTRACT-P3] 전(前) 사업장 오너 — 보존된 계약서 단건 상세 조회
// 호출 가능 조건: data.historicalOwnerUid == callerUid (자기 자신만)
// IDOR 방어: contractId 단독 보유는 접근 근거 아님 — historicalOwnerUid 일치 필수
// 반환: 상세 DTO (pdfUrl, snapshot, articles, slots 포함; 서명URL·내부필드 미포함)
// Input:  { contractId: string }
// Output: 계약서 상세 DTO
export const callableGetHistoricalContractById = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    // ── 1. 인증 ────────────────────────────────────────────────────────────────
    if (!request.auth) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");
    const callerUid = request.auth.uid;

    // ── 2. 입력 검증 ───────────────────────────────────────────────────────────
    const {contractId} = (request.data ?? {}) as {contractId?: string};
    if (
      !contractId ||
      typeof contractId !== "string" ||
      contractId.trim().length === 0
    ) {
      throw new HttpsError("invalid-argument", "contractId가 필요합니다.");
    }

    // ── 3. 문서 조회 ───────────────────────────────────────────────────────────
    const docSnap = await db
      .collection("employment_contracts")
      .doc(contractId.trim())
      .get();

    // ── 4. not-found 마스킹 (문서 미존재 + 소유자 불일치 동일 응답) ────────────
    // IDOR: contractId 단독으로 타인 계약 존재 여부 노출 방지
    if (!docSnap.exists) {
      throw new HttpsError("not-found", "계약서를 찾을 수 없습니다.");
    }
    const data = docSnap.data()!;
    if (
      typeof data.historicalOwnerUid !== "string" ||
      data.historicalOwnerUid !== callerUid
    ) {
      throw new HttpsError("not-found", "계약서를 찾을 수 없습니다.");
    }

    // ── 5. 상세 DTO 구성 ───────────────────────────────────────────────────────
    // snapshot/articles/slots: 계약 당시 동결 데이터 (live business/user 불필요)
    // 서명 이미지 URL 미포함: historical read UI는 PDF 중심 (raw 서명 이미지 불필요)
    // historicalOwnerUid 미포함: 내부 인가 필드, 호출자에게 반환 불필요
    const snapshotData = (
      typeof data.snapshot === "object" && data.snapshot !== null
        ? data.snapshot
        : {}
    ) as Record<string, unknown>;
    const articlesData = Array.isArray(data.articles) ? data.articles : [];
    // [GAP-D] applicationId 노출 차단 — 운영 참조 키는 historical archive DTO 미포함
    // 계약 내용(근무일/시간/임금)만 추출; 말폼 슬롯은 skip하지 않고 null-safe 처리
    const slotsData = (Array.isArray(data.slots) ? data.slots : [])
      .filter((s): s is Record<string, unknown> => typeof s === "object" && s !== null)
      .map((s) => ({
        workDate:  s["workDate"]  ?? null,
        startTime: s["startTime"] ?? null,
        endTime:   s["endTime"]   ?? null,
        wage:      s["wage"]      ?? null,
        wageType:  s["wageType"]  ?? null,
      }));

    const detail: Record<string, unknown> = {
      contractId:       docSnap.id,
      businessId:       data.businessId       ?? null,
      businessName:     snapshotData.businessName ?? null,
      workerId:         data.workerId          ?? null,
      workerName:       snapshotData.workerName   ?? null,
      status:           data.status            ?? null,
      isLongTerm:       data.isLongTerm        ?? null,
      createdAt:        data.createdAt         ?? null,
      employerSignedAt: data.employerSignedAt  ?? null,
      workerSignedAt:   data.workerSignedAt    ?? null,
      contractVoidedAt: data.contractVoidedAt  ?? null,
      voidReason:       data.voidReason        ?? null,
      snapshot:         snapshotData,
      articles:         articlesData,
      slots:            slotsData,
      // pdfUrl: 인가 완료 후 실제 URL 반환 (null이면 PDF 미생성 계약)
      pdfUrl:
        typeof data.pdfUrl === "string" &&
        (data.pdfUrl as string).trim().length > 0
          ? data.pdfUrl
          : null,
    };

    return serializeFirestoreData(detail);
  }
);

// ─── Staffing Readiness (D0~D+7) ────────────────────────────────────────────
/**
 * callableGetStaffingReadiness — Home 인력 블록용 D0~D+7 staffing 현황
 *
 * scope:     서버 결정 (client-supplied businessIds 신뢰 금지)
 * SubAdmin:  selectedBusinessId server-validated + canManageTo || canManageWorkers gate
 * OWNER:     uid.managedBusinessIds 전체 집계 (selectedBusinessId 무시)
 *
 * Flex TO:   slot.workDetailCounts[wdId].confirmedCount — per-wdId 부족분 합산
 *            shortage = Σ max(wd.requiredCount - confirmed, 0) per wdId
 *            (초과확정 wdId의 surplus가 다른 wdId 부족분을 상쇄하지 않음)
 * Contract TO: CONFIRMED + CONTRACT_PENDING application 날짜 전개
 *            shortage = max(totalRequired - confirmedOnDay, 0) per TO per day
 *
 * PENDING:   secondary signal only — capacity 계산 미포함
 * 거짓 0:    쿼리 실패 시 available:false 반환 — 0과 "데이터 없음" 구분
 */
export const callableGetStaffingReadiness = onCall(
  {region: "asia-northeast3", enforceAppCheck: true},
  async (request) => {
    if (!request.auth) throw new HttpsError("unauthenticated", "로그인이 필요합니다.");
    const uid = request.auth.uid;

    // ── 1. 사용자 문서 — role + businessIds 서버 결정 ──────────────────────
    const userSnap = await db.collection("users").doc(uid).get();
    if (!userSnap.exists) throw new HttpsError("not-found", "사용자를 찾을 수 없습니다.");
    const userData = userSnap.data()!;
    const role = (userData["role"] as string) ?? "";

    let businessIds: string[];
    let isSubAdmin = false;

    if (role === "BUSINESS_ADMIN" || role === "SUPER_ADMIN") {
      businessIds = (userData["managedBusinessIds"] as string[] | undefined) ?? [];
    } else if (role === "USER") {
      const subAdminIds = (userData["subAdminBusinessIds"] as string[] | undefined) ?? [];
      if (subAdminIds.length === 0) {
        throw new HttpsError("permission-denied", "관리자만 접근 가능합니다.");
      }
      isSubAdmin = true;
      businessIds = subAdminIds;
    } else {
      throw new HttpsError("permission-denied", "관리자만 접근 가능합니다.");
    }

    // SubAdmin scope narrowing (OWNER scope는 argument 무시)
    if (isSubAdmin) {
      const {selectedBusinessId} = (request.data ?? {}) as {selectedBusinessId?: string};
      if (typeof selectedBusinessId === "string" && selectedBusinessId.trim().length > 0) {
        const trimmedId = selectedBusinessId.trim();
        if (!businessIds.includes(trimmedId)) {
          throw new HttpsError("permission-denied", "해당 사업장에 대한 접근 권한이 없습니다.");
        }
        businessIds = [trimmedId];
      }
    }

    if (businessIds.length === 0) {
      return {available: true, partial: false, failedBusinessCount: 0, days: []};
    }

    // ── 2. SubAdmin 권한 맵 (canManageTo || canManageWorkers 필요) ──────────
    const permMap: Record<string, Record<string, boolean>> = {};
    if (isSubAdmin) {
      const memberSnaps = await Promise.all(
        businessIds.map((bizId) =>
          db.collection("businesses").doc(bizId).collection("members").doc(uid).get()
        )
      );
      memberSnaps.forEach((snap, i) => {
        permMap[businessIds[i]] =
          ((snap.data() ?? {})["permissions"] ?? {}) as Record<string, boolean>;
      });
      businessIds = businessIds.filter((bizId) => {
        const p = permMap[bizId] ?? {};
        return p["canManageTo"] === true || p["canManageWorkers"] === true;
      });
      if (businessIds.length === 0) {
        // [CROSS-DOMAIN-R5.1] 여기의 `available`은 권한 플래그가 아니라
        //   **조회에 성공했는가**다(AH-V2-03.1 — 부분 실패를 false로 알리는 용도).
        //   권한 0개는 조회 실패가 아니라 scope가 빈 것이므로 true를 유지한다.
        //   Task 단위 권한 표현은 callableGetAdminHomeSummary의
        //   actions.*.available이 따로 맡는다.
        //   다만 홈 인력 블록이 이 empty를 `부족 없음`처럼 읽히게 하는지는
        //   별개 문제다 → [CORRECTION-READINESS-SCOPE-COPY]
        return {available: true, partial: false, failedBusinessCount: 0, days: []};
      }
    }

    // ── 3. D0~D+7 날짜 배열 (KST) ─────────────────────────────────────────
    const todayKSTMidnight = srvHomeKSTMidnight();
    const todayMs = todayKSTMidnight.getTime();
    const N_DAYS = 8; // D0~D+7 포함

    const KST_MS = 9 * 3600 * 1000;
    const KST_WEEKDAY_KO = ["일", "월", "화", "수", "목", "금", "토"];

    // KST 기준 날짜 번호 (YYYYMMDD integer, 대소 비교용)
    const srfKstDateNum = (d: Date): number => {
      const kst = new Date(d.getTime() + KST_MS);
      return (
        kst.getUTCFullYear() * 10000 +
        (kst.getUTCMonth() + 1) * 100 +
        kst.getUTCDate()
      );
    };
    // KST 기준 요일 한글 (workDays 비교용)
    const srfKstWeekdayKo = (d: Date): string => {
      const kst = new Date(d.getTime() + KST_MS);
      return KST_WEEKDAY_KO[kst.getUTCDay()];
    };

    const dateDates: Date[] = [];
    const dateLabels: string[] = [];
    const dateDateNums: number[] = [];
    for (let i = 0; i < N_DAYS; i++) {
      const d = new Date(todayMs + i * 24 * 3600 * 1000);
      dateDates.push(d);
      dateLabels.push(srvHomeDateLabel(d));
      dateDateNums.push(srfKstDateNum(d));
    }

    const d0Ts  = admin.firestore.Timestamp.fromDate(todayKSTMidnight);
    const d7EndTs = admin.firestore.Timestamp.fromMillis(todayMs + N_DAYS * 24 * 3600 * 1000);

    // ── 4. 사업장명 일괄 조회 ─────────────────────────────────────────────
    const bizNameMap: Record<string, string> = {};
    const bizSnaps = await Promise.allSettled(
      businessIds.map((bizId) => db.collection("businesses").doc(bizId).get())
    );
    bizSnaps.forEach((r, i) => {
      if (r.status === "fulfilled" && r.value.exists) {
        const bd = r.value.data()!;
        bizNameMap[businessIds[i]] =
          (bd["businessName"] as string | undefined) ??
          (bd["name"] as string | undefined) ??
          businessIds[i];
      } else {
        bizNameMap[businessIds[i]] = businessIds[i];
      }
    });

    // ── 5. 사업장별 병렬 처리 ─────────────────────────────────────────────
    interface SrfDayAcc {
      required:  number;
      confirmed: number;
      shortage:  number;
      pending:   number; // 합산 중간값 — pendingAvailable=false 시 최종 null
    }
    interface SrfBizResult {
      bizId:            string;
      success:          boolean; // false → 주요 staffing 쿼리 실패 → available:false
      pendingAvailable: boolean; // false → pending 쿼리 실패 → pendingCount:null (ERROR≠ZERO)
      days:             SrfDayAcc[];
      // [HOME-V2-08B.2] Home lifecycle signal — 화면 분기용이지 KPI가 아니다.
      // publishedCount: 살아있는 SCHEDULED+ACTIVE+FULL 수
      // hasDraft: 살아있는 DRAFT가 하나라도 있는가
      publishedCount: number;
      hasDraft: boolean;
    }

    const bizResults = await Promise.allSettled(
      businessIds.map(async (bizId): Promise<SrfBizResult> => {
        const dayAcc: SrfDayAcc[] = Array.from({length: N_DAYS}, () => ({
          required: 0, confirmed: 0, shortage: 0, pending: 0,
        }));
        let success          = true;
        let pendingAvailable = true; // pending 쿼리 성공 여부 (secondary signal)

        // ── 5a. TO 목록 조회 (ACTIVE | SCHEDULED | FULL, isDeleted != true) ─────
        //
        // [HOME-V2-08B.2] FULL을 population에 넣는다.
        //
        // syncTOStats(applications onDocumentWritten)가 인원이 차는 순간 TO를
        // 자동으로 FULL로 바꾼다 — ACTIVE는 IMMUTABLE_TO_STATUSES에 없다.
        // 즉 FULL은 예외가 아니라 "모집이 성공적으로 끝난" 일상적 상태다.
        // 그런데 이 쿼리가 FULL을 빼고 있어서, 그 TO의 required와 confirmed가
        // **둘 다** 집계에서 사라졌다. 오늘 근무가 전부 충원되면 required가 0이
        // 되어 hasTodayTarget이 false가 되고, Home은 `오늘 예정된 인력 운영이
        // 없어요`라고 말하면서 바로 아래에 `현재 출근 6/6`을 함께 보여줬다
        // (출근 수치는 applications를 직접 읽어 TO status와 무관하다).
        // 운영이 잘될수록 Home이 비어 보이는 구조였다.
        //
        // DRAFT는 넣지 않는다. 공개된 적 없는 공고에는 확정 지원서가 없으므로
        // required만 더해지고 confirmed가 0이라 shortage 전량이 유령으로 잡힌다.
        const tosSnap = await db.collection("tos")
          .where("businessId", "==", bizId)
          .where("status", "in", ["ACTIVE", "SCHEDULED", "FULL"])
          .get();

        type WdEntry = {id: string; required: number};
        interface FlexTO  { toId: string; wds: WdEntry[] }
        interface ContractTO {
          toId:        string;
          wds:         WdEntry[];
          totalRequired: number;
          rangeStart?: admin.firestore.Timestamp;
          rangeEnd?:   admin.firestore.Timestamp;
          workDays?:   string[];
        }

        const flexTOs:     FlexTO[]     = [];
        const contractTOs: ContractTO[] = [];
        // [HOME-V2-08B.2] publishedPostingCount — 위 population을 그대로 센다.
        //   FULL이 합류했으므로 이 집합이 곧 SCHEDULED+ACTIVE+FULL이다.
        //   별도 조회 없이 같은 루프에서 얻으므로 추가 read가 0이다.
        let publishedCount = 0;

        for (const toDoc of tosSnap.docs) {
          const d = toDoc.data();
          if (d["isDeleted"] === true) continue; // soft delete
          publishedCount++;
          const toType = (d["type"] as string | undefined) ?? "";
          const rawWDs = (d["workDetails"] as unknown[] | undefined) ?? [];
          // [SYSTEM-INTEGRATION-R0] 이 배열은 **CONTRACT 전용**이다.
          //
          //   이전에는 `w["id"]`를 읽고 `id.length > 0`으로 걸렀다. 그런데
          //   WorkDetailData.toMap()이 내보내는 키는 `workType`·`requiredCount`와
          //   (있을 때만) `wdId`이고 `id`는 스키마에 존재하지 않는다. 그래서
          //   모든 workDetail이 필터에서 탈락했고, FLEX는 빈 배열을 돌아
          //   required가 한 번도 더해지지 않았으며 CONTRACT는 totalRequired가 0이라
          //   `if (to.totalRequired === 0) return;`에서 즉시 반환됐다.
          //   결과적으로 이 callable은 **어떤 TO에 대해서도** 0이 아닌 required를
          //   만들어낼 수 없었다. 공고 목록은 같은 필드를 필터 없이 읽어 `필요 30`을
          //   보여주는데 Home은 `예정된 근무 없음`이라고 말하는 모순이 여기서 났다.
          //
          //   FLEX는 여기서 식별자를 얻지 않는다 — TO-level workDetails에는 wdId가
          //   없고(서버는 slot 생성 때만 generateWdId()를 돌린다), 슬롯마다 독립
          //   wdId가 발급되므로 TO 한 벌로는 어떤 날짜의 counter와도 join할 수 없다.
          //   canonical join은 5b에서 slot 자신의 workDetails로 수행한다.
          const wds: WdEntry[] = rawWDs
            .filter((w): w is Record<string, unknown> =>
              typeof w === "object" && w !== null)
            .map((w) => ({
              id:       ((w["wdId"] as string | undefined) ?? "").trim(),
              required: Math.max(0, (w["requiredCount"] as number | undefined) ?? 0),
            }));

          if (toType === "flex") {
            flexTOs.push({toId: toDoc.id, wds});
          } else if (toType === "contract") {
            contractTOs.push({
              toId:          toDoc.id,
              wds,
              totalRequired: wds.reduce((s, w) => s + w.required, 0),
              rangeStart:    d["rangeStart"]  as admin.firestore.Timestamp | undefined,
              rangeEnd:      d["rangeEnd"]    as admin.firestore.Timestamp | undefined,
              workDays:      d["workDays"]    as string[] | undefined,
            });
          }
        }

        // ── 5b. Flex TOs: 슬롯 기반 per-wdId 인원 집계 ──────────────────
        const flexResults = await Promise.allSettled(
          flexTOs.map(async (to) => {
            const slotsSnap = await db
              .collection("tos").doc(to.toId).collection("slots")
              .where("date", ">=", d0Ts)
              .where("date", "<", d7EndTs)
              .get();

            for (const slotDoc of slotsSnap.docs) {
              const sd = slotDoc.data();
              const slotTs = sd["date"] as admin.firestore.Timestamp | undefined;
              if (!slotTs) continue;

              // 슬롯 날짜 → day index (KST 자정 UTC 기반)
              const dayIdx = Math.round(
                (slotTs.toMillis() - todayMs) / (24 * 3600 * 1000)
              );
              if (dayIdx < 0 || dayIdx >= N_DAYS) continue;

              const wdc = (sd["workDetailCounts"] as
                Record<string, {confirmedCount?: number}> | undefined) ?? {};

              // [SYSTEM-INTEGRATION-R2.4 §4/§19] 종료된 모집 단위는 부족이 아니다.
              //
              //   callableGetDayStaffingDetail은 슬롯/업무 종료를 읽어 shortage를
              //   0으로 만들고 충원 CTA도 내린다. 이 reader가 같은 사실을 보지
              //   않으면 Home은 `3명 부족`이라 말하고 같은 날짜를 연 다이얼로그는
              //   `모집 종료`라고 말한다 — 같은 근무에 truth가 둘이 된다.
              //   required·confirmed는 그대로 보고하고 shortage만 0이다
              //   (DayStaffingRow.shortage와 같은 계약).
              const slotClosed =
                sd["isManualClosed"] === true || sd["status"] === "closed";

              // [SYSTEM-INTEGRATION-R0] canonical join — **같은 슬롯 문서 안에서** 한다.
              //   slot.workDetails[].wdId ↔ slot.workDetailCounts[wdId]
              //   필요 인원도 슬롯 자신의 requiredCount를 쓴다. 날짜마다 workDetail
              //   구성이 다를 수 있으므로 TO 한 벌을 모든 날짜에 적용하면 안 된다.
              //   슬롯은 이미 읽은 문서라 추가 read가 0이다.
              const rawSlotWDs =
                (sd["workDetails"] as unknown[] | undefined) ?? [];
              const slotWds = rawSlotWDs
                .filter((w): w is Record<string, unknown> =>
                  typeof w === "object" && w !== null)
                .map((w) => ({
                  wdId: ((w["wdId"] as string | undefined) ?? "").trim(),
                  required: Math.max(
                    0, (w["requiredCount"] as number | undefined) ?? 0),
                  // 업무 단위 종료도 슬롯 종료와 같다 (WorkDetailData.isClosed).
                  closed: slotClosed ||
                    w["isManualClosed"] === true || w["closedAt"] != null,
                }));

              // per-wdId shortage 합산 — 초과확정 wdId surplus는 다른 wdId 부족분 상쇄 금지
              for (const wd of slotWds) {
                if (wd.wdId.length === 0 || !(wd.wdId in wdc)) {
                  // [SYSTEM-INTEGRATION-R0] DATA CONTRACT ERROR ≠ ZERO.
                  //   이전에는 조용히 skip했다. 그러면 required가 빠진 채로 정상
                  //   응답이 되어 Home이 `예정된 근무 없음`·`전원 충원` 같은 **부정
                  //   주장**을 하게 된다 — 확인하지 못한 것을 없다고 말하는 것이다.
                  //   throw하면 이 사업장이 success=false가 되어 available/partial로
                  //   내려가고, 클라이언트의 기존 error·partial 표면이 처리한다.
                  throw new Error(
                    "[staffingReadiness] WORKDETAIL_CONTRACT_BROKEN: " +
                    `TO ${to.toId} slot ${slotDoc.id} wdId "${wd.wdId}" ` +
                    `(counts keys: ${Object.keys(wdc).join(",")})`
                  );
                }
                const cnt = wdc[wd.wdId]?.confirmedCount ?? 0;
                const confirmed = Math.max(0, cnt);
                // 종료된 단위는 채울 수 없으므로 부족이 아니다.
                const shortage  = wd.closed ?
                  0 : Math.max(0, wd.required - confirmed);
                dayAcc[dayIdx].required  += wd.required;
                dayAcc[dayIdx].confirmed += confirmed;
                dayAcc[dayIdx].shortage  += shortage;
              }
            }
          })
        );
        flexResults.forEach((r, i) => {
          if (r.status === "rejected") {
            console.error(`[staffingReadiness] ${bizId} flex TO ${flexTOs[i].toId} slot 실패:`, r.reason);
            success = false;
          }
        });

        // ── 5c. Contract TOs: 날짜 전개 기반 인원 집계 ──────────────────
        const contractResults = await Promise.allSettled(
          contractTOs.map(async (to) => {
            if (to.totalRequired === 0) return;

            // 확정 지원서 조회
            const appsSnap = await db.collection("applications")
              .where("toId", "==", to.toId)
              .where("status", "in", CONFIRMED_STATUSES)
              .get();

            const toRangeStartNum = to.rangeStart
              ? srfKstDateNum(to.rangeStart.toDate()) : 0;
            const toRangeEndNum = to.rangeEnd
              ? srfKstDateNum(to.rangeEnd.toDate()) : 99991231;

            for (let i = 0; i < N_DAYS; i++) {
              const dayNum = dateDateNums[i];
              const dayWkd = srfKstWeekdayKo(dateDates[i]);

              // TO 활성 여부: rangeStart..rangeEnd + workDays
              if (dayNum < toRangeStartNum || dayNum > toRangeEndNum) continue;
              if (to.workDays && to.workDays.length > 0 &&
                  !to.workDays.includes(dayWkd)) continue;

              dayAcc[i].required += to.totalRequired;

              // 해당 날짜에 활성인 확정 지원서 수
              let confirmedOnDay = 0;
              for (const appDoc of appsSnap.docs) {
                const ad = appDoc.data();

                // 지원서 날짜 범위
                const appStartTs = ad["workDate"]    as admin.firestore.Timestamp | undefined;
                const appEndTs   = ad["workEndDate"] as admin.firestore.Timestamp | undefined;
                const appStartNum = appStartTs ? srfKstDateNum(appStartTs.toDate()) : 0;
                const appEndNum   = appEndTs   ? srfKstDateNum(appEndTs.toDate())   : 99991231;
                if (dayNum < appStartNum || dayNum > appEndNum) continue;

                // extraWorkDates (workDays 무관 근무일)
                const extras = ad["extraWorkDates"] as admin.firestore.Timestamp[] | undefined;
                const isExtra = Array.isArray(extras) &&
                  extras.some((ts) => srfKstDateNum(ts.toDate()) === dayNum);

                if (!isExtra) {
                  // 지원서 workDays 필터
                  const appWorkDays = ad["workDays"] as string[] | undefined;
                  if (appWorkDays && appWorkDays.length > 0 &&
                      !appWorkDays.includes(dayWkd)) continue;

                  // leaveDates 필터
                  const leaves = ad["leaveDates"] as admin.firestore.Timestamp[] | undefined;
                  if (Array.isArray(leaves) &&
                      leaves.some((ts) => srfKstDateNum(ts.toDate()) === dayNum)) continue;
                }

                confirmedOnDay++;
              }

              dayAcc[i].confirmed += confirmedOnDay;
              dayAcc[i].shortage  += Math.max(0, to.totalRequired - confirmedOnDay);
            }
          })
        );
        contractResults.forEach((r, i) => {
          if (r.status === "rejected") {
            console.error(`[staffingReadiness] ${bizId} contract TO ${contractTOs[i].toId} 실패:`, r.reason);
            success = false;
          }
        });

        // ── 5d. Pending 지원서 (secondary signal) — 실패 시 pendingAvailable=false ──
        // ERROR ≠ ZERO 원칙: 쿼리 실패를 0으로 표현하지 않음.
        // main staffing(required/confirmed/shortage)은 영향 없음.
        try {
          const pendingSnap = await db.collection("applications")
            .where("businessId", "==", bizId)
            .where("status",     "==", "PENDING")
            .where("workDate",   ">=", d0Ts)
            .where("workDate",   "<",  d7EndTs)
            .get();

          for (const pDoc of pendingSnap.docs) {
            const pd = pDoc.data();
            const wdTs = pd["workDate"] as admin.firestore.Timestamp | undefined;
            if (!wdTs) continue;
            const pendingDayNum = srfKstDateNum(wdTs.toDate());
            const idx = dateDateNums.indexOf(pendingDayNum);
            if (idx >= 0) dayAcc[idx].pending++;
          }
        } catch (e) {
          console.warn(
            `[staffingReadiness] ${bizId} pending 쿼리 실패 → pendingCount:null 처리:`, e
          );
          pendingAvailable = false;
        }

        // ── 5e. [HOME-V2-08B.2] 살아있는 DRAFT 존재 여부 ────────────────
        //
        // `isDeleted == false` equality 한 방으로 끝낼 수 없다. 소프트 삭제는
        // 2026-08-10에 도입됐고 backfill을 하지 않았다("마이그레이션 불필요",
        // getEffectiveActivePostingCount 주석 참조). 그래서 그 이전에 만든
        // 살아있는 DRAFT에는 필드가 아예 없고, equality 쿼리는 그것들을
        // 조용히 빠뜨린다. 필드 부재는 쿼리로 표현할 수 없다.
        //
        // limit(N) 한 장만 보고 false로 확정하지도 않는다. 삭제된 DRAFT가 N개
        // 쌓여 있고 N+1번째가 살아있으면, Home이 실제 초안을 못 보고
        // `현재 등록된 공고가 없어요`를 띄운다.
        //
        // 그래서 cursor로 끝까지 훑되, **살아있는 문서를 만나는 즉시 멈춘다.**
        // 정상 계정의 best case는 1 read다. worst case(삭제된 DRAFT만 잔뜩)만
        // 전량을 보는데, 그때는 실제로 전량을 봐야 false를 말할 수 있다.
        let hasDraft = false;
        try {
          const DRAFT_PAGE = 100;
          let cursor: admin.firestore.QueryDocumentSnapshot | undefined;
          for (;;) {
            let q = db.collection("tos")
              .where("businessId", "==", bizId)
              .where("status", "==", "DRAFT")
              .orderBy("createdAt", "desc")
              .limit(DRAFT_PAGE);
            if (cursor) q = q.startAfter(cursor);
            const page = await q.get();
            if (page.empty) break;
            const live = page.docs.find(
              (doc) => doc.data()["isDeleted"] !== true);
            if (live) {
              hasDraft = true;
              break;
            }
            if (page.size < DRAFT_PAGE) break; // 컬렉션 소진 → false 확정
            cursor = page.docs[page.size - 1];
          }
        } catch (e) {
          // [ERROR ≠ ZERO] 조회 실패를 '초안 없음'으로 내리지 않는다.
          //   이 사업장을 실패로 표시해 기존 partial 계약에 태운다 —
          //   Home이 장애를 '공고 없음'으로 오인하면 안 된다.
          console.error(`[staffingReadiness] ${bizId} DRAFT 존재 조회 실패:`, e);
          success = false;
        }

        return {bizId, success, pendingAvailable, days: dayAcc,
          publishedCount, hasDraft};
      })
    );

    // ── 6. 전체 집계 ──────────────────────────────────────────────────────
    // pendingCount: number | null
    //   0     = 실제 대기 없음 (actual zero)
    //   N > 0 = 실제 대기 N건
    //   null  = pending 쿼리 실패 (한 사업장이라도 실패 → 전체 날짜 null)
    //           "데이터 없음"과 "0"을 구분 (ERROR≠ZERO 원칙)
    interface SrfBizDayEntry {
      businessId:     string;
      businessName:   string;
      requiredCount:  number;
      confirmedCount: number;
      shortageCount:  number;
      pendingCount:   number | null; // null = 이 사업장 pending 쿼리 실패
    }
    interface SrfDayEntry {
      date:           string;
      requiredCount:  number;
      confirmedCount: number;
      shortageCount:  number;
      pendingCount:   number | null; // null = 일부 사업장 pending 쿼리 실패
      byBusiness:     SrfBizDayEntry[];
    }

    // pendingCount 중간 합산용 (overallPendingAvailable 확정 후 null 또는 값으로 최종 처리)
    const aggPending: number[] = new Array(N_DAYS).fill(0);

    const aggDays: SrfDayEntry[] = dateLabels.map((label) => ({
      date: label, requiredCount: 0, confirmedCount: 0,
      shortageCount: 0, pendingCount: null, byBusiness: [],
    }));

    // [AH-V2-03] 사업장 단위 부분 실패를 전체 실패로 만들지 않는다.
    //   실패한 사업장의 데이터는 합산에서 제외하고(불완전한 값을 정상 합계에
    //   섞지 않는다), 몇 개가 빠졌는지를 failedBusinessCount로 전달한다.
    //   [AH-V2-03.1] 쓸 수 있는 부분합이 있다는 신호는 available이 아니라
    //   partial이다. available은 "전부 성공"이라는 기존 의미를 유지한다.
    let okBusinessCount     = 0;
    let failedBusinessCount = 0;
    let overallPendingAvailable = true;
    // [HOME-V2-08B.2] lifecycle signal — 성공한 사업장만 합산한다.
    //   실패한 사업장을 0으로 치면 장애가 '공고 없음'으로 둔갑한다.
    //   부분합이라는 사실은 기존 partial/failedBusinessCount가 전달한다.
    let publishedPostingCount = 0;
    let hasDraftPosting = false;

    for (const r of bizResults) {
      if (r.status === "rejected") {
        console.error("[staffingReadiness] 사업장 처리 실패:", r.reason);
        failedBusinessCount++;
        overallPendingAvailable = false; // rejected 사업장 pending 불명
        continue;
      }
      const {bizId, success, pendingAvailable, days} = r.value;
      if (!success) {
        // TO 쿼리 실패 → 이 사업장 집계는 불완전하다. 합산에서 제외.
        console.error(`[staffingReadiness] ${bizId} staffing 집계 불완전 — 합산 제외`);
        failedBusinessCount++;
        overallPendingAvailable = false;
        continue;
      }
      okBusinessCount++;
      if (!pendingAvailable) overallPendingAvailable = false;
      // scope 전체 합산 — 한 사업장에만 공고가 있어도 운영 상태다.
      publishedPostingCount += r.value.publishedCount;
      if (r.value.hasDraft) hasDraftPosting = true;

      const bizName = bizNameMap[bizId] ?? bizId;
      for (let i = 0; i < N_DAYS; i++) {
        const {required, confirmed, shortage, pending} = days[i];
        aggDays[i].requiredCount  += required;
        aggDays[i].confirmedCount += confirmed;
        aggDays[i].shortageCount  += shortage;
        if (pendingAvailable) aggPending[i] += pending;

        if (required > 0 || confirmed > 0 || shortage > 0 || pending > 0) {
          aggDays[i].byBusiness.push({
            businessId:     bizId,
            businessName:   bizName,
            requiredCount:  required,
            confirmedCount: confirmed,
            shortageCount:  shortage,
            pendingCount:   pendingAvailable ? pending : null,
          });
        }
      }
    }

    // pending 최종 처리: 모든 사업장 성공 시 합산값, 실패 시 null 유지
    if (overallPendingAvailable) {
      for (let i = 0; i < N_DAYS; i++) aggDays[i].pendingCount = aggPending[i];
    }

    // [AH-V2-03.1] available은 기존 의미 그대로 "전체 조회 성공"을 뜻한다.
    //   partial을 모르는 구 클라이언트는 available=false만 보고 ERROR로 빠지므로,
    //   부분합을 전체 합계로 오인하지 않는다. (OLD CLIENT + NEW SERVER 안전)
    //   신규 클라이언트는 partial을 available보다 먼저 해석해 부분합을 쓴다.
    //
    //   ALL_SUCCESS   available=true  partial=false
    //   PARTIAL       available=false partial=true
    //   ALL_FAILED    available=false partial=false
    //   EMPTY_SCOPE   available=true  partial=false
    // [HOME-V2-08B.2] lifecycle signal의 유효성은 별도 필드를 만들지 않고
    //   기존 available/partial로 판단한다. partial이면 두 값은 부분합이므로
    //   소비자는 '공고 없음'을 확정하면 안 된다.
    return {
      available: failedBusinessCount === 0,
      partial: okBusinessCount > 0 && failedBusinessCount > 0,
      failedBusinessCount,
      days: aggDays,
      publishedPostingCount,
      hasDraftPosting,
    };
  }
);

// [Phase 6 완료] callableGetLegacyBankCleanupStatus 삭제 — diagnostic CF, 역할 완료.
